func TestRegionSeatsGeneralizesTheTwoSeatTopology(t *testing.T) {
	domains := []string{"FAULT-DOMAIN-1", "FAULT-DOMAIN-2", "FAULT-DOMAIN-3"}
	two, err := RegionSeats(oci.RegionGRU, domains, SeatsPerRegion)
	if err != nil {
