type reattachTestFleet struct {
	*placementTestFleet
	states         map[string]string
	attachments    []oci.Attachment
	detaches       []oci.FencedDetachRequest
	attachRequests []oci.VolumeAttachRequest
	permits        []oci.VolumeMountPermit
