controller_constructor.text:
func (controller *Controller) currentTime() time.Time {
	if controller.now != nil {
		return controller.now()
	}
	return time.Now()
}

// StartController validates one region-bound reconciler. Run owns the periodic
// lifecycle; Tick is exposed for deterministic callers and tests.
func StartController(ctx context.Context, config Config, store Store, fencer authority.Fencer, fleet oci.Fleet, hosts HostView, desired DesiredWriter, resolveArtifact ArtifactResolver) (*Controller, error) {
	if ctx == nil || ctx.Err() != nil {
		return nil, errors.New("placement controller requires a live context")
	}
	if err := config.validate(); err != nil {
		return nil, err
	}
	if store == nil || fencer == nil || fleet == nil || hosts == nil || desired == nil || resolveArtifact == nil {
		return nil, errors.New("placement controller requires durable state, authority, OCI fleet, host view, desired writer and artifact admission")
	}
	if fleet.Region() != config.Region {
		return nil, errors.New("placement controller region differs from its pinned OCI fleet")
	}
	if config.TickInterval == 0 {
		config.TickInterval = defaultTickInterval
	}
	return &Controller{config: config, store: store, fencer: fencer, fleet: fleet, hosts: hosts, desired: desired, resolveArtifact: resolveArtifact}, nil
}

func (config Config) validate() error {
	if !validToken(config.Cell) || !knownRegion(config.Region) || !validToken(config.ManagedOwner) ||
		!validToken(config.Environment) || !validToken(config.MemberRole) || config.FleetGeneration == 0 ||
		!strings.HasPrefix(config.ImageID, "ocid1.image.") || len(config.ImageID) > 255 || strings.ContainsAny(config.ImageID, " \t\r\n") ||
		!positive(config.Resources) ||
		config.Resources.CPU > 4096 || config.Resources.MemoryBytes > 1<<50 || config.Resources.DiskBytes > 1<<50 {
		return errors.New("placement controller config has an invalid cell, region, owner, role, or resource profile")
	}
	if err := config.VolumeDeadlines.Validate(); err != nil {
		return err
	}
	if config.LostMemberGrace < 0 || config.LostMemberGrace > 7*24*time.Hour {
		return errors.New("placement lost member grace must be between zero and seven days")
	}
	if config.TickInterval < 0 || config.TickInterval != 0 && (config.TickInterval < minTickInterval || config.TickInterval > maxTickInterval) {
		return errors.New("placement tick interval must be zero or between 100ms and 5m")
	}
	if len(config.FaultDomains) < 2 || len(config.FaultDomains) > 3 || config.FaultDomains[0] == config.FaultDomains[1] {
		return errors.New("placement region requires at least two distinct OCI fault domains")
	}
	for _, domain := range config.FaultDomains {
		if len(domain) != len("FAULT-DOMAIN-1") || !strings.HasPrefix(domain, "FAULT-DOMAIN-") || domain[len(domain)-1] < '1' || domain[len(domain)-1] > '3' {
			return fmt.Errorf("invalid configured OCI fault domain %q", domain)
		}
	}
	return nil
}

controller_tick.text:
func (controller *Controller) Tick(ctx context.Context) error {
	if controller == nil || ctx == nil {
		return errors.New("placement controller and context are required")
	}
	if err := ctx.Err(); err != nil {
		return err
	}
	snapshot := controller.fencer.Current()
	if !snapshot.CanMutate() {
		return nil
	}
	epoch := snapshot.Epoch
	intents, err := controller.store.ListIntents(ctx)
	if err != nil {
		return err
	}
	if len(intents) > maxIntentCount {
		return errors.New("placement intent list exceeds its safety bound")
	}
	instances, err := controller.fleet.Observe(oci.WithCachedVerification(ctx))
	if err != nil {
		return fmt.Errorf("observe region-bound OCI fleet: %w", err)
	}
	instanceByID := make(map[string]oci.Instance, len(instances))
	for _, instance := range instances {
		if instance.ID == "" || instance.Node == "" || instance.Region != controller.config.Region || instance.ETag == "" {
			return errors.New("OCI fleet returned an incomplete or cross-region instance")
		}
		if _, exists := instanceByID[instance.ID]; exists {
			return fmt.Errorf("OCI fleet returned duplicate instance %q", instance.ID)
		}
		instanceByID[instance.ID] = instance
	}
	statuses, err := controller.hosts.ListHosts(ctx)
	if err != nil {
		return fmt.Errorf("read current host registrations and reports: %w", err)
	}
	statusByNode := make(map[string]host.HostStatus, len(statuses))
	for _, status := range statuses {
		node := status.Registration.Node
		if node == "" {
			return errors.New("host view returned a registration without a node")
		}
		if _, exists := statusByNode[node]; exists {
			return fmt.Errorf("host view returned duplicate node %q", node)
		}
		statusByNode[node] = status
	}
	seenIntents := make(map[string]struct{}, len(intents))
	// A failing placement must not starve independent ones: its error is
	// reported with the pass while later placements still advance.
	var placementErrs []error
intents:
	for _, intent := range intents {
		if err := intent.Validate(); err != nil {
			return err
		}
		identity := intent.DatabaseID + "\x00" + intent.PartitionID
		if _, exists := seenIntents[identity]; exists {
			return fmt.Errorf("%w: duplicate database/partition intent", ErrInvalidIntent)
		}
		seenIntents[identity] = struct{}{}
		if _, err := controller.store.ReadTerminalIntent(ctx, intent.DatabaseID, intent.PartitionID); err == nil {
			controller.hold(fmt.Sprintf("database %s/%s has a committed terminal teardown fence", intent.DatabaseID, intent.PartitionID))
			continue
		} else if !errors.Is(err, authority.ErrNotFound) {
			return fmt.Errorf("read terminal workload fence for %s/%s: %w", intent.DatabaseID, intent.PartitionID, err)
		}
		if intent.SchemaVersion != IntentSchemaVersion || intent.PayloadDigest() == "" {
			controller.hold(fmt.Sprintf("database %s/%s has no admitted managed placement profile; host reconciliation is held", intent.DatabaseID, intent.PartitionID))
			continue
		}
		if len(intent.ActiveRegions) != 1 {
			controller.hold(fmt.Sprintf("database %s/%s has %d regions; current TerraBase outbound sender supports exactly two members in one region", intent.DatabaseID, intent.PartitionID, len(intent.ActiveRegions)))
			continue
		}
		members, err := controller.store.ListMembers(ctx, intent.DatabaseID, intent.PartitionID)
		if err != nil {
			return err
		}
		if len(members) > maxMemberStates {
			return fmt.Errorf("placement member state for %s/%s exceeds its bound", intent.DatabaseID, intent.PartitionID)
		}
		if !slices.Contains(intent.ActiveRegions, controller.config.Region) {
			if len(members) > 0 && controller.config.OnHold != nil {
				controller.config.OnHold(fmt.Sprintf("database %s/%s regional retirement is held; trusted replication, quorum, drain, writer-stop, and retained-volume evidence is required", intent.DatabaseID, intent.PartitionID))
			}
			continue
		}
		seats, err := controller.localSeats(intent)
		if err != nil {
			return err
		}
		rosterDigest, err := intent.CanonicalRosterDigest()
		if err != nil {
			return err
		}
		rowsBySeat := make(map[string]CanonicalRosterRow, len(seats))
		manifestsBySeat := make(map[string]RuntimeManifest, len(seats))
		manifestDigestsBySeat := make(map[string]string, len(seats))
		rosterHeld := false
		for _, seat := range seats {
			row, err := intent.RosterRowForSeat(seat)
			if err != nil {
				controller.hold(fmt.Sprintf("member %s has no signed roster row matching its configured seat; host reconciliation is held: %v", seat.MemberID, err))
				rosterHeld = true
				break
			}
			rowsBySeat[seat.MemberID] = row
			manifest, err := intent.RuntimeManifestForSeat(seat)
			if err != nil {
				controller.hold(fmt.Sprintf("member %s has no signed runtime manifest: %v", seat.MemberID, err))
				rosterHeld = true
				break
			}
			manifestDigest, err := manifest.Digest()
			if err != nil {
				return err
			}
			manifestsBySeat[seat.MemberID] = manifest
			manifestDigestsBySeat[seat.MemberID] = manifestDigest
		}
		if rosterHeld {
			continue
		}
		profile, err := intent.ManagedHostProfile(controller.config.Region)
		if err != nil {
			return err
		}
		profileDigest, err := profile.ProfileDigest()
		if err != nil {
			return err
		}
		memberByID := make(map[string]VersionedMemberState, len(members))
		for _, member := range members {
			if member.State.DatabaseID != intent.DatabaseID || member.State.PartitionID != intent.PartitionID {
				return fmt.Errorf("%w: member state escaped database/partition scope", ErrStoreCorrupt)
			}
			if _, exists := memberByID[member.State.MemberID]; exists {
				return fmt.Errorf("%w: duplicate member state %q", ErrStoreCorrupt, member.State.MemberID)
			}
			memberByID[member.State.MemberID] = member
		}
		held := false
		for _, seat := range seats {
			versioned, exists := memberByID[seat.MemberID]
			if !exists {
				continue
			}
			state := versioned.State
			if state.Region != seat.Region || state.Kind != seat.Kind || state.FailureDomain != seat.FailureDomain {
				return fmt.Errorf("%w: admitted placement seat conflicts with durable member identity", ErrStoreCorrupt)
			}
			if state.SchemaVersion != managedUpdateMemberStateSchemaVersion ||
				state.CanonicalRosterRow != rowsBySeat[seat.MemberID] ||
				state.RuntimeManifest != manifestsBySeat[seat.MemberID] ||
				state.RuntimeManifestDigest != manifestDigestsBySeat[seat.MemberID] ||
				state.CanonicalRosterDigest != rosterDigest ||
				state.AuthorityReference != intent.CanonicalRoster.Authority ||
				state.IntentPayloadDigest == "" || state.ManagedHostProfileDigest == "" ||
				state.IntentPayloadDigest != intent.PayloadDigest() || state.ManagedHostProfile != profile ||
				state.ManagedHostProfileDigest != profileDigest || state.IntentGeneration != intent.Generation {
				controller.hold(fmt.Sprintf("member %s has no matching immutable roster, authority reference, or placement profile; an explicit new attempt is required", seat.MemberID))
				held = true
				break
			}
			if state.Stage == StageRemoved {
				controller.hold(fmt.Sprintf("removed member %s requires an explicit reconciled new attempt", seat.MemberID))
				held = true
				break
			}
		}
		if held {
			continue
		}
		managedUpdateActed, err := controller.reconcileManagedUpdate(ctx, epoch, intent, seats, memberByID)
		if err != nil {
			placementErrs = append(placementErrs, fmt.Errorf("%s/%s: %w", intent.DatabaseID, intent.PartitionID, err))
			continue
		}
		if managedUpdateActed {
			return errors.Join(placementErrs...)
		}
		for _, seat := range seats {
			versioned, exists := memberByID[seat.MemberID]
			if !exists {
				state := controller.initialState(intent, seat, rowsBySeat[seat.MemberID], rosterDigest,
					profile, profileDigest, manifestsBySeat[seat.MemberID], manifestDigestsBySeat[seat.MemberID], 1)
				if _, err := controller.persist(ctx, epoch, 0, state); err != nil {
					return errors.Join(append(placementErrs, err)...)
				}
				return errors.Join(placementErrs...)
			}
			acted, err := controller.replaceLostMember(ctx, epoch, intent, seat, versioned, seats, memberByID,
				instanceByID, statusByNode)
			if err != nil {
				placementErrs = append(placementErrs, fmt.Errorf("%s/%s: %w", intent.DatabaseID, intent.PartitionID, err))
				continue intents
			}
			if acted {
				return errors.Join(placementErrs...)
			}
			acted, err = controller.advanceMember(ctx, epoch, intent, seat, versioned, instanceByID, statusByNode)
			if err != nil {
				placementErrs = append(placementErrs, fmt.Errorf("%s/%s: %w", intent.DatabaseID, intent.PartitionID, err))
				continue intents
			}
			if acted {
				return errors.Join(placementErrs...)
			}
		}
	}
	return errors.Join(placementErrs...)
}

controller_advance.text:
func (controller *Controller) advanceMember(
	ctx context.Context,
	epoch uint64,
	intent Intent,
	seat Seat,
	versioned VersionedMemberState,
	instances map[string]oci.Instance,
	statuses map[string]host.HostStatus,
) (bool, error) {
	state := versioned.State
	if state.ManagedRuntimeTarget.Phase == ManagedUpdateSeatHeld {
		controller.hold(fmt.Sprintf("managed update %s is durably held: %s",
			state.ManagedRuntimeTarget.OperationID, state.ManagedRuntimeTarget.Outcome))
		return false, nil
	}
	switch state.Stage {
	case StagePreparedHost:
		if !controller.runtimeArtifactReady(ctx, state, seat) {
			return false, nil
		}
		if err := controller.guard(ctx, epoch); err != nil {
			return false, err
		}
		instance, err := controller.fleet.EnsureHost(ctx, pinnedEnsureRequest(state))
		if err != nil {
			return false, fmt.Errorf("ensure TerraBase member host %s/%s: %w", intent.DatabaseID, seat.MemberID, err)
		}
		if err := controller.validateEnsuredInstance(instance, state, seat); err != nil {
			return false, err
		}
		state.Stage = StageAwaitingHost
		state.HostNode = instance.Node
		state.InstanceID = instance.ID
		state.InstanceETag = instance.ETag
		state.OperationID = memberOperationID(intent, seat.MemberID, state.HostAttempt, "host")
		_, err = controller.persist(ctx, epoch, versioned.Revision, state)
		return true, err
	case StageAwaitingHost:
		instance, exists := instances[state.InstanceID]
		if !exists {
			// Retrying EnsureHost with the same durable create key recovers an
			// unknown launch outcome without adopting a tag-matched resource.
			if !controller.runtimeArtifactReady(ctx, state, seat) {
				return false, nil
			}
			if err := controller.guard(ctx, epoch); err != nil {
				return false, err
			}
			instance, err := controller.fleet.EnsureHost(ctx, pinnedEnsureRequest(state))
			if err != nil {
				return false, fmt.Errorf("recover TerraBase member host %s/%s: %w", intent.DatabaseID, seat.MemberID, err)
			}
			if err := controller.validateEnsuredInstance(instance, state, seat); err != nil {
				return false, err
			}
			state.HostNode, state.InstanceID, state.InstanceETag = instance.Node, instance.ID, instance.ETag
			_, err = controller.persist(ctx, epoch, versioned.Revision, state)
			return true, err
		}
		if err := controller.validateObservedInstance(instance, state, seat); err != nil {
			return false, err
		}
		status, admitted := controller.admittedHost(intent, state, instance, statuses)
		if !admitted {
			return false, nil
		}
		if state.VolumeID == "" {
			state.Stage = StagePreparedVolume
		} else {
			state.Stage = StagePreparedAttach
		}
		state.HostGeneration = status.Registration.Generation
		state.InstanceETag = instance.ETag
		state.OperationID = memberOperationID(intent, seat.MemberID, state.HostAttempt, "admitted")
		_, err := controller.persist(ctx, epoch, versioned.Revision, state)
		return true, err
	case StagePreparedVolume:
		if _, exists := instances[state.InstanceID]; !exists {
			controller.hold(fmt.Sprintf("member %s OCI host is not currently observed; retained volume creation is withheld", seat.MemberID))
			return false, nil
		}
		var sizeGB int64
		if state.VolumeID == "" {
			var err error
			sizeGB, err = volumeSizeGB(controller.config.Resources.DiskBytes)
			if err != nil {
				return false, err
			}
			if !controller.runtimeArtifactReady(ctx, state, seat) {
				return false, nil
			}
		}
		instance, fresh, err := controller.freshVolumeHost(ctx, intent, seat, state)
		if err != nil {
			return false, err
		}
		if !fresh {
			return false, nil
		}
		// The member's own host image must qualify before its volume is
		// created or attached.
		if err := controller.verifyHostImage(ctx, instance); err != nil {
			return false, err
		}
		if state.VolumeID != "" {
			state.Stage = StagePreparedAttach
			state.OperationID = memberOperationID(intent, seat.MemberID, state.HostAttempt, "attach")
			_, err := controller.persist(ctx, epoch, versioned.Revision, state)
			return true, err
		}
		// Admission may change during the live OCI reads.
		if !controller.runtimeArtifactReady(ctx, state, seat) {
			return false, nil
		}
		if err := controller.guard(ctx, epoch); err != nil {
			return false, err
		}
		member, err := seatMemberName(seat.Region, seat.MemberID)
		if err != nil {
			return false, err
		}
		// A member name always has a data name; the fleet checks it again.
		name, _ := naming.Data(member)
		volume, err := controller.fleet.CreateRetainedVolume(ctx, oci.VolumeCreateRequest{
			Name: name, DatabaseID: intent.DatabaseID, PartitionID: intent.PartitionID,
			MemberID:  seat.MemberID,
			CreateKey: volumeCreateKey(intent, seat), SizeGB: sizeGB,
		})
		if err != nil {
			return false, fmt.Errorf("create or recover retained member volume %s/%s: %w", intent.DatabaseID, seat.MemberID, err)
		}
		if volume.ID == "" || volume.CreateKey != volumeCreateKey(intent, seat) || volume.Region != controller.config.Region ||
			volume.Owner != controller.config.ManagedOwner || volume.Generation != controller.config.FleetGeneration {
			return false, errors.New("OCI fleet returned a retained volume with mismatched durable identity")
		}
		if volume.SizeGB < sizeGB {
			// The volume was created under an earlier, smaller resource profile.
			if _, fresh, err := controller.freshVolumeHost(ctx, intent, seat, state); err != nil {
				return false, err
			} else if !fresh {
				return false, nil
			}
			grown, err := controller.growVolume(ctx, epoch, intent, volume, sizeGB)
			if err != nil {
				return false, fmt.Errorf("retained member volume %s/%s is %d GiB, below the desired %d GiB: %w",
					intent.DatabaseID, seat.MemberID, volume.SizeGB, sizeGB, err)
			}
			if grown.ID != volume.ID || grown.SizeGB < sizeGB {
				return false, errors.New("OCI fleet returned a resized retained volume with mismatched durable identity")
			}
		}
		state.VolumeID = volume.ID
		state.Stage = StagePreparedAttach
		state.OperationID = memberOperationID(intent, seat.MemberID, state.HostAttempt, "attach")
		_, err = controller.persist(ctx, epoch, versioned.Revision, state)
		return true, err
	case StagePreparedAttach:
		instance, exists := instances[state.InstanceID]
		if !exists {
			// An instance with an ATTACHING volume is withheld from
			// observation; a requested attach still runs against its
			// deadline.
			controller.holdStalledAttachRequest(seat.MemberID, state)
			return false, nil
		}
		if err := controller.validateObservedInstance(instance, state, seat); err != nil {
			return false, err
		}
		status, admitted := controller.admittedHost(intent, state, instance, statuses)
		if !admitted || status.Registration.Generation != state.HostGeneration {
			return false, nil
		}
		if !controller.runtimeArtifactReady(ctx, state, seat) {
			return false, nil
		}
		if err := controller.verifyHostImage(ctx, instance); err != nil {
			return false, err
		}
		if state.PreviousInstanceID != "" {
			return controller.reattachRetainedVolume(ctx, epoch, intent, seat, versioned)
		}
		var attachment *oci.Attachment
		for index := range instance.Attachments {
			if instance.Attachments[index].VolumeID == state.VolumeID {
				if instance.Attachments[index].InstanceID != state.InstanceID {
					return false, oci.ErrRetainedVolumeInUse
				}
				attachment = &instance.Attachments[index]
				break
			}
		}
		if attachment == nil {
			if state.AttachRequestedAt.IsZero() {
				// Record when the attach starts, durably, so its deadline
				// survives restarts and settle-wait failures.
				state.AttachRequestedAt = controller.currentTime().UTC()
				revision, err := controller.persist(ctx, epoch, versioned.Revision, state)
				if err != nil {
					return false, err
				}
				versioned.Revision = revision
			}
			if err := controller.guard(ctx, epoch); err != nil {
				return false, err
			}
			attached, err := controller.fleet.AttachRetainedVolume(ctx, oci.VolumeAttachRequest{
				DatabaseID: intent.DatabaseID, PartitionID: intent.PartitionID,
				VolumeID: state.VolumeID, InstanceID: state.InstanceID,
				IdempotencyKey: memberOperationID(intent, seat.MemberID, state.HostAttempt, "attach-volume"),
			})
			if err != nil {
				controller.holdStalledAttachRequest(seat.MemberID, state)
				return false, fmt.Errorf("attach retained member volume %s/%s: %w", intent.DatabaseID, seat.MemberID, err)
			}
			attachment = &attached
		}
		state.AttachmentID = attachment.ID
		if attachment.State == "ATTACHED" {
			state.AttachRequestedAt = time.Time{}
			state.Stage = StageAwaitingRuntimeContract
			state.OperationID = memberOperationID(intent, seat.MemberID, state.HostAttempt, "runtime-hold")
		} else if attachment.State == "ATTACHING" {
			state.Stage = StageAwaitingAttach
			state.OperationID = memberOperationID(intent, seat.MemberID, state.HostAttempt, "attach-wait")
		} else {
			controller.hold(fmt.Sprintf("member %s retained volume attachment is %s; desired state remains withheld", seat.MemberID, attachment.State))
			return false, nil
		}
		_, err := controller.persist(ctx, epoch, versioned.Revision, state)
		return true, err
	case StageAwaitingAttach:
		instance, exists := instances[state.InstanceID]
		if !exists {
			return false, nil
		}
		if err := controller.validateObservedInstance(instance, state, seat); err != nil {
			return false, err
		}
		status, admitted := controller.admittedHost(intent, state, instance, statuses)
		if !admitted || status.Registration.Generation != state.HostGeneration {
			return false, nil
		}
		for _, attachment := range instance.Attachments {
			if attachment.ID != state.AttachmentID || attachment.VolumeID != state.VolumeID || attachment.InstanceID != state.InstanceID {
				continue
			}
			switch attachment.State {
			case "ATTACHED":
				if !controller.runtimeArtifactReady(ctx, state, seat) {
					return false, nil
				}
				if err := controller.verifyHostImage(ctx, instance); err != nil {
					return false, err
				}
				state.AttachRequestedAt = time.Time{}
				state.Stage = StageAwaitingRuntimeContract
				state.OperationID = memberOperationID(intent, seat.MemberID, state.HostAttempt, "runtime-hold")
				_, err := controller.persist(ctx, epoch, versioned.Revision, state)
				return true, err
			case "ATTACHING":
				controller.holdStuckAttachment(seat.MemberID, attachment.ID, state)
				return false, nil
			default:
				controller.hold(fmt.Sprintf("member %s retained volume attachment is %s; desired state remains withheld", seat.MemberID, attachment.State))
				return false, nil
			}
		}
		controller.hold(fmt.Sprintf("member %s retained volume attachment is not positively observed; desired state remains withheld", seat.MemberID))
		return false, nil
	case StagePreparedDesired:
		if acted, err := controller.holdTimedOutManagedCanary(ctx, epoch, intent, versioned); acted || err != nil {
			return acted, err
		}
		if !controller.preparedPinsMatch(intent, state, seat) {
			controller.hold(fmt.Sprintf("member %s prepared desired pins changed; launch is held", seat.MemberID))
			return false, nil
		}
		// The fresh observation validated the member's bound host; its image
		// must qualify before the desired effect.
		instance, fresh, err := controller.freshPreparedInputs(ctx, epoch, intent, seat, state)
		if err != nil {
			return false, err
		}
		if !fresh {
			return false, nil
		}
		if err := controller.verifyHostImage(ctx, instance); err != nil {
			return false, err
		}
		desired, err := controller.memberDesired(epoch, intent, state, seat)
		if err != nil {
			return false, err
		}
		if err := controller.guard(ctx, epoch); err != nil {
			return false, err
		}
		receipt, err := controller.desired.ApplyDesired(ctx, desired)
		if err != nil {
			return false, fmt.Errorf("apply prepared TerraBase desired for %s: %w", seat.MemberID, err)
		}
		if receipt.Generation != state.DesiredGeneration || receipt.Revision == 0 {
			return false, errors.New("host desired writer returned a mismatched receipt")
		}
		state.Stage = StageAwaitingHealthy
		state.OperationID = memberOperationID(intent, seat.MemberID, state.HostAttempt, "await-healthy")
		_, err = controller.persist(ctx, epoch, versioned.Revision, state)
		return true, err
	case StageAwaitingRuntimeContract:
		instance, exists := instances[state.InstanceID]
		if !exists {
			controller.hold(fmt.Sprintf("member %s OCI host is not currently observed; retained volume is kept", seat.MemberID))
			return false, nil
		}
		if err := controller.validateObservedInstance(instance, state, seat); err != nil {
			return false, err
		}
		status, admitted := controller.admittedHost(intent, state, instance, statuses)
		if !admitted || status.Registration.Generation != state.HostGeneration {
			controller.hold(fmt.Sprintf("member %s is awaiting an exact managed OCI registration and current host session", seat.MemberID))
			return false, nil
		}
		attachment, attached := observedAttachment(instance, state)
		if !attached || !validObservedAttachment(attachment) {
			controller.hold(fmt.Sprintf("member %s retained volume is not observed ATTACHED; desired state remains withheld", seat.MemberID))
			return false, nil
		}
		if !controller.runtimeArtifactReady(ctx, state, seat) {
			return false, nil
		}
		if err := controller.verifyHostImage(ctx, instance); err != nil {
			return false, err
		}
		if _, err := host.ManagedMountPath(state.RuntimeManifest.ManagedRuntimeRoot, controller.memberBinding(intent, state)); err != nil {
			controller.hold(fmt.Sprintf("member %s has no safe managed mount path: %v", seat.MemberID, err))
			return false, nil
		}
		state.AttachmentDevice, state.AttachmentETag = attachment.Device, attachment.ETag
		state.DesiredGeneration = state.IntentGeneration
		state.Stage = StagePreparedDesired
		state.OperationID = memberOperationID(intent, seat.MemberID, state.HostAttempt, "prepare-desired")
		_, err := controller.persist(ctx, epoch, versioned.Revision, state)
		return true, err
	case StageAwaitingHealthy:
		if acted, err := controller.holdTimedOutManagedCanary(ctx, epoch, intent, versioned); acted || err != nil {
			return acted, err
		}
		if instance, exists := instances[state.InstanceID]; exists {
			if err := controller.validateObservedInstance(instance, state, seat); err != nil {
				return false, err
			}
			if status, admitted := controller.admittedHost(intent, state, instance, statuses); admitted &&
				status.Registration.Generation == state.HostGeneration {
				if state.ManagedRuntimeTarget.OperationID != "" {
					current, err := controller.managedUpdatePrepareIsCurrent(ctx, state)
					if err != nil {
						return false, err
					}
					if !current {
						controller.hold(fmt.Sprintf("member %s managed canary authority is no longer current", seat.MemberID))
						return false, nil
					}
				}
				if controller.hasServingReport(intent, state, instance, status) {
					if state.ManagedRuntimeTarget.OperationID != "" {
						target := state.ManagedRuntimeTarget
						target.Phase = ManagedUpdateSeatCanaryServing
						target.Outcome = string(authority.ManagedUpdateCanaryServing)
						_, err := controller.commitManagedUpdateOutcome(ctx, epoch, state,
							authority.ManagedUpdateCanaryServing, target.Outcome,
							func(verifyCtx context.Context, update ManagedUpdateIntent,
								prepared authority.ManagedUpdateRecord,
							) error {
								return controller.verifyManagedCanaryServingAtAuthorityCommit(verifyCtx, epoch, update, prepared, versioned)
							})
						if err != nil {
							return false, err
						}
						state.ManagedRuntimeTarget = target
					}
					state.Stage = StageServing
					state.OperationID = memberOperationID(intent, seat.MemberID, state.HostAttempt, "serving")
					_, err := controller.persist(ctx, epoch, versioned.Revision, state)
					return true, err
				}
				if state.ManagedRuntimeTarget.OperationID != "" && hasCurrentFailedCanaryReport(status, state,
					controller.config.Environment, controller.config.MemberRole) {
					outcome := "candidate-reported-failure"
					target := state.ManagedRuntimeTarget
					target.Phase, target.Outcome = ManagedUpdateSeatHeld, outcome
					_, err := controller.commitManagedUpdateOutcome(ctx, epoch, state,
						authority.ManagedUpdateHeld, outcome,
						func(verifyCtx context.Context, update ManagedUpdateIntent,
							prepared authority.ManagedUpdateRecord,
						) error {
							return controller.verifyManagedCanaryFailureAtAuthorityCommit(verifyCtx, epoch, update, versioned,
								controller.config.Environment, controller.config.MemberRole)
						})
					if err != nil {
						return false, err
					}
					state.ManagedRuntimeTarget = target
					state.OperationID = digestToken("u", state.DatabaseID, state.PartitionID,
						state.ManagedRuntimeTarget.OperationID, state.MemberID, "held")
					_, err = controller.persist(ctx, epoch, versioned.Revision, state)
					return true, err
				}
			}
		}
		controller.hold(fmt.Sprintf("member %s awaits a current mounted process and independent TerraBase serving proof", seat.MemberID))
		return false, nil
	case StageServing:
		if instance, exists := instances[state.InstanceID]; exists {
			if err := controller.validateObservedInstance(instance, state, seat); err != nil {
				return false, err
			}
			if status, admitted := controller.admittedHost(intent, state, instance, statuses); admitted &&
				status.Registration.Generation == state.HostGeneration &&
				controller.hasServingReport(intent, state, instance, status) {
				return false, nil
			}
		}
		if state.ManagedRuntimeTarget.OperationID != "" {
			controller.hold(fmt.Sprintf("managed canary member %s lost its current candidate serving proof; it remains held without peer promotion", seat.MemberID))
			return false, nil
		}
		state.Stage = StageAwaitingRuntimeContract
		state.OperationID = memberOperationID(intent, seat.MemberID, state.HostAttempt, "runtime-hold")
		_, err := controller.persist(ctx, epoch, versioned.Revision, state)
		controller.hold(fmt.Sprintf("member %s lost current host, attachment, mounted process, or TerraBase serving proof; it is held without replacement", seat.MemberID))
		return true, err
	case StageRemoveCandidate, StageCordoned, StageDraining, StageDrained, StageStorageHandled, StageTerminated:
		controller.hold(fmt.Sprintf("member %s is in retirement stage %s; retirement actions require the integrated evidence-driven scale-in path", seat.MemberID, state.Stage))
		return false, nil
	case StageRemoved:
		return false, nil
	default:
		return false, fmt.Errorf("%w: unknown member stage %q", ErrStoreCorrupt, state.Stage)
	}
}

controller_seats.text:
func (controller *Controller) verifyHostImage(ctx context.Context, instance oci.Instance) error {
	if err := controller.fleet.VerifyHostImage(ctx, instance.ImageID); err != nil {
		return fmt.Errorf("current managed OCI host image qualification: %w", err)
	}
	return nil
}

func (controller *Controller) localSeats(intent Intent) ([]Seat, error) {
	if !slices.Contains(intent.ActiveRegions, controller.config.Region) {
		return nil, nil
	}
	return RegionSeats(controller.config.Region, controller.config.FaultDomains, SeatsPerRegion)
}

controller_identity.text:
func (controller *Controller) validateObservedInstance(instance oci.Instance, state MemberState, seat Seat) error {
	privateIP, _, err := net.SplitHostPort(state.RuntimeManifest.ReplicationListenAddress)
	if err != nil || privateIP == "" || instance.PrivateIP != privateIP {
		return errors.New("observed OCI instance differs from the prepared private IP")
	}
	if instance.ID != state.InstanceID || instance.Node != state.HostNode || instance.CreateKey != state.CreateKey ||
		instance.Region != controller.config.Region || instance.FaultDomain != seat.FailureDomain || instance.ETag == "" ||
		state.InstanceETag == "" || !controller.instanceMatchesPinnedProfile(instance, state) {
		return errors.New("observed OCI instance differs from the durable TerraBase member binding")
	}
	return nil
}

func (controller *Controller) instanceMatchesPinnedProfile(instance oci.Instance, state MemberState) bool {
	compute := state.ManagedHostProfile.Compute
	return instance.Owner == controller.config.ManagedOwner && instance.Generation == controller.config.FleetGeneration &&
		controller.imageAllowed(instance.ImageID) && controller.instanceMatchesPinnedBootDescriptor(instance, state) &&
		instance.Shape == compute.Shape && instance.WholeOCPUs == compute.WholeOCPUs &&
		instance.MemoryInGBs == compute.MemoryInGBs && instance.PlacementProfileDigest == state.ManagedHostProfileDigest &&
		instance.PlacementGeneration == state.IntentGeneration
}

// imageAllowed reports whether a member host may run imageID: the pinned
// image or one the cell's allow-list qualifies.
func (controller *Controller) imageAllowed(imageID string) bool {
	allowed := controller.config.AllowedImages
	return imageID == controller.config.ImageID || allowed != nil && slices.Contains(allowed(), imageID)
}

// instanceMatchesPinnedBootDescriptor rebuilds the descriptor the host was
// launched with, from its seat binding and its own (allowed) image.
func (controller *Controller) instanceMatchesPinnedBootDescriptor(instance oci.Instance, state MemberState) bool {
	descriptor := hostboot.Descriptor{
		SchemaVersion: hostboot.SchemaVersion, Cell: controller.config.Cell, Region: string(controller.config.Region),
		Node: instance.Node, Owner: controller.config.ManagedOwner, CreateKey: state.CreateKey,
		ImageID: instance.ImageID, FleetGeneration: controller.config.FleetGeneration,
		DatabaseID: state.DatabaseID, PartitionID: state.PartitionID, SeatID: state.MemberID,
		HostAttempt: state.HostAttempt, IntentGeneration: state.IntentGeneration,
		IntentPayloadDigest: state.IntentPayloadDigest, CanonicalRosterDigest: state.CanonicalRosterDigest,
		ManagedHostProfileDigest: state.ManagedHostProfileDigest, RuntimeManifestDigest: state.RuntimeManifestDigest,
	}
	digest, err := descriptor.Digest()
	return err == nil && digest == instance.BootDescriptorSHA256
}

func (controller *Controller) admittedHost(intent Intent, state MemberState, instance oci.Instance, statuses map[string]host.HostStatus) (host.HostStatus, bool) {
	status, exists := statuses[instance.Node]
	if !exists {
		return host.HostStatus{}, false
	}
	registration := status.Registration
	binding := registration.ManagedOCI
	if !status.Verified || !time.Now().Before(status.SessionExpiresAt) || binding == nil ||
		registration.Cell != controller.config.Cell || registration.Node != instance.Node ||
		registration.Environment != controller.config.Environment || registration.FailureDomain != instance.FaultDomain ||
		!slices.Contains(registration.Roles, controller.config.MemberRole) ||
		registration.Capacity.CPU < controller.config.Resources.CPU ||
		registration.Capacity.MemoryBytes < controller.config.Resources.MemoryBytes ||
		registration.Capacity.DiskBytes < controller.config.Resources.DiskBytes ||
		binding.Region != string(controller.config.Region) || binding.InstanceID != instance.ID ||
		binding.Owner != controller.config.ManagedOwner || binding.FleetGeneration != controller.config.FleetGeneration ||
		binding.CreateKey != instance.CreateKey {
		return host.HostStatus{}, false
	}
	row := state.CanonicalRosterRow
	roster := intent.CanonicalRoster
	pins := host.ManagedRegistrationPins{
		Placement: host.ManagedPlacementBinding{
			DatabaseID: state.DatabaseID, PartitionID: state.PartitionID, SeatID: state.MemberID,
			IntentGeneration: state.IntentGeneration, IntentPayloadDigest: state.IntentPayloadDigest,
			CanonicalRosterDigest: state.CanonicalRosterDigest, ManagedHostProfileDigest: state.ManagedHostProfileDigest,
		},
		Member: host.ManagedMemberBinding{
			Scope: host.MemberScope{
				ClusterID: roster.ClusterID, TenantID: roster.TenantID, DatabaseID: roster.DatabaseID,
				ShardID: roster.ShardID, MemberID: row.MemberID, Incarnation: row.Incarnation,
			},
			HostAttempt: state.HostAttempt,
		},
		OCI: host.ManagedOCIBinding{
			Region: string(instance.Region), InstanceID: instance.ID, Owner: instance.Owner,
			FleetGeneration: instance.Generation, CreateKey: instance.CreateKey,
		},
		FailureDomain:          row.FailureDomain,
		AllocatableMemoryBytes: state.ManagedHostProfile.AllocatableMemoryBytes,
		SystemReserveBytes:     state.ManagedHostProfile.SystemReserveBytes,
	}
	if err := host.ValidateManagedRegistrationPins(registration, pins); err != nil {
		return host.HostStatus{}, false
	}
	return status, true
}

controller_report.text:
func (controller *Controller) hasServingReport(intent Intent, state MemberState, instance oci.Instance, status host.HostStatus) bool {
	manifest := state.EffectiveRuntimeManifest()
	attachment, attached := observedAttachment(instance, state)
	if !attached || !validObservedAttachment(attachment) ||
		attachment.Device != state.AttachmentDevice || attachment.ETag != state.AttachmentETag {
		return false
	}
	var survivor memberstatus.Survivor
	for _, row := range intent.CanonicalRoster.Rows {
		if row.MemberID == manifest.ReplicationPeerMemberID && row.MemberID != state.CanonicalRosterRow.MemberID {
			survivor = memberstatus.Survivor{MemberID: row.MemberID, Incarnation: row.Incarnation}
			break
		}
	}
	if survivor.MemberID == "" {
		return false
	}
	mountPath, err := host.ManagedMountPath(manifest.ManagedRuntimeRoot, controller.memberBinding(intent, state))
	if err != nil {
		return false
	}
	now := time.Now()
	for _, report := range status.Reports {
		managed := report.Managed
		if report.Cell != controller.config.Cell || report.Node != status.Registration.Node ||
			report.Environment != controller.config.Environment || report.Role != controller.config.MemberRole ||
			report.Generation != state.DesiredGeneration || report.Digest != manifest.ArtifactDigest ||
			report.State != "running" || report.ObservedAt.IsZero() || report.ObservedAt.After(now.Add(2*time.Second)) ||
			now.Sub(report.ObservedAt) >= host.ReportMaxAge || managed == nil || managed.ServingProof == nil ||
			managed.Member != controller.memberBinding(intent, state) ||
			managed.Authority != (host.MemberAuthority{
				Epoch: state.AuthorityReference.Epoch, ConfigurationID: state.AuthorityReference.ConfigurationID,
				CertificateSHA256: state.AuthorityReference.CertificateSHA256,
				TLSLeafSHA256:     state.CanonicalRosterRow.TLSLeafSHA256,
			}) || managed.OCI != (host.ManagedOCIBinding{
			Region: string(state.Region), InstanceID: state.InstanceID, Owner: controller.config.ManagedOwner,
			FleetGeneration: controller.config.FleetGeneration, CreateKey: state.CreateKey,
		}) || managed.VolumeID != state.VolumeID || managed.AttachmentID != state.AttachmentID ||
			managed.AttachmentETag != attachment.ETag || managed.FileSystemUUID != manifest.FileSystemUUID ||
			managed.FileSystemType != manifest.FileSystemType || managed.MountDevice != attachment.Device ||
			managed.MountPath != mountPath || managed.MountID == 0 || managed.ProcessPID < 2 ||
			managed.ProcessStart == "" || !strings.HasPrefix(managed.ProcessCgroup, "/") ||
			!managed.StorageRecovered || !managed.ListenerReady {
			continue
		}
		proof := managed.ServingProof
		if memberstatus.VerifyReportedServing(*proof, memberstatus.Identity{
			Process: memberstatus.Process{PID: managed.ProcessPID, StartNonce: managed.ProcessBootID},
			Scope: memberstatus.Scope{
				ClusterID: intent.CanonicalRoster.ClusterID, TenantID: intent.CanonicalRoster.TenantID,
				DatabaseID: intent.CanonicalRoster.DatabaseID, ShardID: intent.CanonicalRoster.ShardID,
				MemberID: state.CanonicalRosterRow.MemberID, Incarnation: state.CanonicalRosterRow.Incarnation,
			},
			Authority: memberstatus.Authority{
				Epoch: state.AuthorityReference.Epoch, ConfigurationID: state.AuthorityReference.ConfigurationID,
				CertificateSHA256: state.AuthorityReference.CertificateSHA256,
				TLSLeafSHA256:     state.CanonicalRosterRow.TLSLeafSHA256,
			},
		}, survivor) == nil {
			return true
		}
	}
	return false
}

controller_persist_guard.text:
func (controller *Controller) beginWorkloadEffect(ctx context.Context, epoch uint64, intent Intent) (func(), error) {
	barrier, ok := controller.fencer.(interface {
		BeginActiveWorkloadEffect(context.Context, uint64, authority.WorkloadScope) (func(), error)
	})
	if !ok {
		return nil, errors.New("placement authority lacks terminal workload fence")
	}
	return barrier.BeginActiveWorkloadEffect(ctx, epoch, authority.WorkloadScope{
		DatabaseID: intent.DatabaseID, PartitionID: intent.PartitionID,
	})
}

func (controller *Controller) persist(ctx context.Context, epoch, revision uint64, state MemberState) (uint64, error) {
	release, err := controller.beginWorkloadEffect(ctx, epoch, Intent{DatabaseID: state.DatabaseID, PartitionID: state.PartitionID})
	if err != nil {
		return 0, err
	}
	defer release()
	state.WriterEpoch = epoch
	state.UpdatedAt = time.Now().UTC()
	return controller.store.CompareAndSwap(ctx, revision, state)
}

func (controller *Controller) guard(ctx context.Context, epoch uint64) error {
	if epoch == 0 || !controller.fencer.Current().CanMutate() || controller.fencer.Current().Epoch != epoch {
		return authority.ErrFenced
	}
	return controller.fencer.Guard(ctx, epoch)
}

controller_holds.text:
func (controller *Controller) holdStuckAttachment(memberID, attachmentID string, state MemberState) {
	since := state.UpdatedAt
	if !state.AttachRequestedAt.IsZero() {
		since = state.AttachRequestedAt
	}
	phase := lifecycle.State{Phase: lifecycle.Attaching, Since: since}
	stuck, expired := lifecycle.Check(phase, controller.currentTime(), controller.config.VolumeDeadlines)
	if !expired {
		return
	}
	controller.hold(fmt.Sprintf("member %s retained volume attachment %s is stuck ATTACHING since %s (%s); remediation %s is required",
		memberID, attachmentID, since.UTC().Format(time.RFC3339), stuck.Reason,
		lifecycle.Remediate(stuck, controller.config.VolumeDeadlines)))
}

// holdStalledAttachRequest reports a requested attach that has not been
// observed ATTACHED within the attach deadline, while the attachment itself
// is not observable (its instance is withheld or the settle wait failed).
func (controller *Controller) holdStalledAttachRequest(memberID string, state MemberState) {
	if state.AttachRequestedAt.IsZero() {
		return
	}
	controller.holdStuckAttachment(memberID, "(not yet observable)", state)
}

func (controller *Controller) hold(reason string) {
	if controller.config.OnHold != nil {
		controller.config.OnHold(reason)
	}
}

func hostCreateKey(intent Intent, seat Seat, attempt uint64) string {
	return digestToken("th", intent.DatabaseID, intent.PartitionID, string(seat.Region), seat.MemberID, fmt.Sprint(attempt))
}

func volumeCreateKey(intent Intent, seat Seat) string {
	return digestToken("tv", intent.DatabaseID, intent.PartitionID, string(seat.Region), seat.MemberID)
}

controller_keys.text:
func memberOperationID(intent Intent, memberID string, attempt uint64, action string) string {
	return digestToken("p", intent.DatabaseID, intent.PartitionID, memberID, fmt.Sprint(intent.Generation), fmt.Sprint(attempt), action)
}

func digestToken(prefix string, values ...string) string {
	return entityid.Derive(prefix, values...)
}

controller_desired.text:
func observedAttachment(instance oci.Instance, state MemberState) (oci.Attachment, bool) {
	if state.VolumeID == "" || state.AttachmentID == "" {
		return oci.Attachment{}, false
	}
	for _, attachment := range instance.Attachments {
		if attachment.ID == state.AttachmentID && attachment.VolumeID == state.VolumeID &&
			attachment.InstanceID == state.InstanceID && attachment.State == "ATTACHED" {
			return attachment, true
		}
	}
	return oci.Attachment{}, false
}

func validObservedAttachment(attachment oci.Attachment) bool {
	return attachment.ETag != "" && strings.HasPrefix(attachment.Device, "/dev/") &&
		filepath.Clean(attachment.Device) == attachment.Device && len(attachment.Device) <= 255 &&
		!strings.ContainsAny(attachment.Device, " \t\r\n\x00") &&
		!attachment.IsReadOnly && !attachment.IsShareable && attachment.IsPvEncryptionInTransitEnabled
}

func (controller *Controller) memberBinding(intent Intent, state MemberState) host.ManagedMemberBinding {
	roster, row := intent.CanonicalRoster, state.CanonicalRosterRow
	return host.ManagedMemberBinding{
		Scope: host.MemberScope{
			ClusterID: roster.ClusterID, TenantID: roster.TenantID, DatabaseID: roster.DatabaseID,
			ShardID: roster.ShardID, MemberID: row.MemberID, Incarnation: row.Incarnation,
		},
		HostAttempt: state.HostAttempt,
	}
}

func (controller *Controller) admittedRuntimeArtifact(ctx context.Context, state MemberState) (AdmittedArtifact, error) {
	manifest := state.EffectiveRuntimeManifest()
	artifact, err := controller.resolveArtifact(ctx, manifest.ArtifactDigest, controller.config.MemberRole, controller.config.Environment)
	if err != nil {
		return AdmittedArtifact{}, err
	}
	if artifact.Digest != manifest.ArtifactDigest || artifact.SourceDigest != manifest.SourceDigest {
		return AdmittedArtifact{}, errors.New("admitted runtime artifact differs from signed source and byte pins")
	}
	if target := state.ManagedRuntimeTarget; target.OperationID != "" &&
		artifact.ManifestDigest != target.ManifestDigest {
		return AdmittedArtifact{}, errors.New("admitted managed update manifest differs from its durable target")
	}
	return artifact, nil
}

func (controller *Controller) runtimeArtifactReady(ctx context.Context, state MemberState, seat Seat) bool {
	if _, err := controller.admittedRuntimeArtifact(ctx, state); err != nil {
		controller.hold(fmt.Sprintf("member %s runtime artifact is not currently admitted: %v", seat.MemberID, err))
		return false
	}
	return true
}

func (controller *Controller) memberDesired(epoch uint64, intent Intent, state MemberState, seat Seat) (host.Desired, error) {
	manifest := state.EffectiveRuntimeManifest()
	binding := controller.memberBinding(intent, state)
	mountPath, err := host.ManagedMountPath(manifest.ManagedRuntimeRoot, binding)
	if err != nil {
		return host.Desired{}, err
	}
	return host.Desired{
		Cell: controller.config.Cell, Node: state.HostNode, Environment: controller.config.Environment,
		Role: controller.config.MemberRole, Digest: manifest.ArtifactDigest,
		Generation: state.DesiredGeneration, AuthorityEpoch: epoch,
		ManagedMember: &host.ManagedMemberLaunch{
			OCI: host.ManagedOCIBinding{
				Region: string(seat.Region), InstanceID: state.InstanceID, Owner: controller.config.ManagedOwner,
				FleetGeneration: controller.config.FleetGeneration, CreateKey: state.CreateKey,
			},
			Member: binding,
			Authority: host.MemberAuthority{
				Epoch: state.AuthorityReference.Epoch, ConfigurationID: state.AuthorityReference.ConfigurationID,
				CertificateSHA256: state.AuthorityReference.CertificateSHA256,
				TLSLeafSHA256:     state.CanonicalRosterRow.TLSLeafSHA256,
			},
			SourceDigest: manifest.SourceDigest, VolumeID: state.VolumeID,
			AttachmentID: state.AttachmentID, AttachmentETag: state.AttachmentETag,
			ProcessMemoryBytes:   state.ManagedHostProfile.ProcessMemoryBytes,
			MemoryHeadroomBytes:  state.ManagedHostProfile.MemoryHeadroomBytes,
			CgroupMemoryMaxBytes: state.ManagedHostProfile.CgroupMemoryMaxBytes,
			SystemReserveBytes:   state.ManagedHostProfile.SystemReserveBytes,
			Runtime: &host.ManagedRuntimePins{
				DevicePath: state.AttachmentDevice, MountPath: mountPath,
				FileSystemUUID: manifest.FileSystemUUID, FileSystemType: manifest.FileSystemType,
				TrustedKeySHA256:                    manifest.TrustedKeySHA256,
				ServerCertificateSHA256:             manifest.ServerCertificateSHA256,
				ServerPrivateKeySHA256:              manifest.ServerPrivateKeySHA256,
				ClientCARootsSHA256:                 manifest.ClientCARootsSHA256,
				ClientManagedMaterialManifestSHA256: manifest.ClientManagedMaterialManifestSHA256,
				SQLSchemaBundleSHA256:               manifest.SQLSchemaBundleSHA256,
				LiveS3ConfigSHA256:                  manifest.LiveS3ConfigSHA256,
				LiveS3TargetSHA256:                  manifest.LiveS3TargetSHA256,
				LiveS3Credential:                    manifest.LiveS3Credential,
				BackupManifestSHA256:                manifest.BackupManifestSHA256,
				BackupS3ConfigSHA256:                manifest.BackupS3ConfigSHA256,
				BackupS3TargetSHA256:                manifest.BackupS3TargetSHA256,
				BackupS3CredentialSHA256:            manifest.BackupS3CredentialSHA256,
				BackupDataKeySHA256:                 manifest.BackupDataKeySHA256,
				BackupOwner:                         manifest.BackupOwner,
				BackupS3Credential:                  manifest.BackupS3Credential,
				BackupDataKey:                       manifest.BackupDataKey,
				ReplicationListenAddress:            manifest.ReplicationListenAddress,
				ReplicationPeerMemberID:             manifest.ReplicationPeerMemberID,
				ReplicationPeerAddress:              manifest.ReplicationPeerAddress,
				ReplicationServerCASHA256:           manifest.ReplicationServerCASHA256,
			},
		},
	}, nil
}

update_validate.text:
func (intent ManagedUpdateIntent) Validate() error {
	if intent.SchemaVersion != ManagedUpdateSchemaVersion || !validToken(intent.Cell) ||
		!validDatabaseKeyID(intent.DatabaseID) || !entityid.Valid(intent.PartitionID) ||
		intent.PlacementGeneration == 0 || !validLowerSHA256Digest(intent.PlacementPayloadDigest) ||
		intent.PlacementSequence == 0 || intent.AuthorityEpoch == 0 || !entityid.Valid(intent.OperationID) ||
		intent.Role != "terrabase" || !validToken(intent.Environment) ||
		!validLowerSHA256Digest(intent.OldArtifactDigest) ||
		!validLowerSHA256Digest(intent.CandidateArtifactDigest) ||
		intent.CandidateArtifactDigest == intent.OldArtifactDigest ||
		!validLowerSHA256Digest(intent.CandidateManifestDigest) ||
		!validLowerSHA256Digest(intent.CandidateSourceDigest) ||
		!entityid.Valid(intent.CanarySeatID) || intent.CanaryDesiredGeneration == 0 ||
		len(intent.Seats) != 2 {
		return errors.New("invalid managed TerraBase update intent")
	}
	if err := intent.DurabilityProfile.Validate(); err != nil {
		return fmt.Errorf("invalid managed update durability profile: %w", err)
	}
	profileDigest, err := intent.DurabilityProfile.Digest()
	if err != nil {
		return fmt.Errorf("digest managed update durability profile: %w", err)
	}
	if !strings.EqualFold(string(intent.DurabilityProfile.Region), intent.Cell) {
		return errors.New("managed update durability profile cell differs from the signed cell")
	}
	if !slices.IsSortedFunc(intent.Seats, func(left, right ManagedUpdateSeat) int {
		return strings.Compare(left.SeatID, right.SeatID)
	}) || !slices.IsSortedFunc(intent.DurabilityProfile.Volumes, func(left, right ManagedUpdateVolumeProfile) int {
		return strings.Compare(left.SeatID, right.SeatID)
	}) {
		return errors.New("managed update seats and durability volumes must be sorted by seat ID")
	}
	canaryFound := false
	seatIDs := make([]string, len(intent.Seats))
	for index, seat := range intent.Seats {
		if err := seat.validate(intent); err != nil {
			return fmt.Errorf("invalid managed update seat %q: %w", seat.SeatID, err)
		}
		if index > 0 && (intent.Seats[index-1].SeatID == seat.SeatID || intent.Seats[index-1].MemberID == seat.MemberID) {
			return errors.New("managed update seats must identify distinct members")
		}
		if index > 0 && (intent.Seats[index-1].HostNode == seat.HostNode ||
			intent.Seats[index-1].OCIInstanceID == seat.OCIInstanceID ||
			intent.Seats[index-1].VolumeID == seat.VolumeID ||
			intent.Seats[index-1].AttachmentID == seat.AttachmentID) {
			return errors.New("managed update seats must retain distinct hosts and volumes")
		}
		seatIDs[index] = seat.SeatID
		if seat.SeatID == intent.CanarySeatID {
			canaryFound = true
			if seat.DesiredGeneration == ^uint64(0) || intent.CanaryDesiredGeneration != seat.DesiredGeneration+1 {
				return errors.New("managed update canary generation must follow its exact predecessor")
			}
		}
	}
	if !canaryFound || len(intent.DurabilityProfile.Volumes) != len(intent.Seats) {
		return errors.New("managed update canary or durability seat set is incomplete")
	}
	for index, volume := range intent.DurabilityProfile.Volumes {
		if volume.SeatID != seatIDs[index] || volume.VolumeID != intent.Seats[index].VolumeID {
			return errors.New("managed update durability profile differs from the pinned seat volumes")
		}
	}
	var evidence ManagedCompatibilityEvidence
	if err := protocol.DecodeStrict(intent.CompatibilityEvidence.Payload, &evidence, protocol.MaxPayloadBytes); err != nil {
		return fmt.Errorf("decode signed managed compatibility evidence: %w", err)
	}
	canonical, err := protocol.EncodeJSON(evidence)
	if err != nil || !bytes.Equal(canonical, intent.CompatibilityEvidence.Payload) {
		return errors.New("signed managed compatibility evidence is not canonical")
	}
	canonicalCell, err := protocol.CanonicalRegion(intent.Cell)
	if err != nil || intent.CompatibilityEvidence.Region != canonicalCell || intent.CompatibilityEvidence.Kind != ManagedCompatibilityEnvelopeKind ||
		intent.CompatibilityEvidence.OperationID != intent.OperationID ||
		intent.CompatibilityEvidence.Generation != intent.CanaryDesiredGeneration ||
		intent.CompatibilityEvidence.Epoch == 0 || intent.CompatibilityEvidence.Actor == "" ||
		intent.CompatibilityEvidence.KeyID == "" || intent.CompatibilityEvidence.Signature == "" ||
		evidence.SchemaVersion != ManagedCompatibilitySchemaVersion || evidence.Cell != intent.Cell ||
		evidence.OperationID != intent.OperationID || evidence.OldArtifactDigest != intent.OldArtifactDigest ||
		evidence.CandidateArtifactDigest != intent.CandidateArtifactDigest ||
		evidence.CandidateManifestDigest != intent.CandidateManifestDigest ||
		evidence.DurabilityProfileSHA256 != profileDigest ||
		!evidence.MixedVersionReplicationSupported || !evidence.ClientDataCompatibilitySupported ||
		!evidence.PersistentFormatReadSupported || !evidence.PersistentFormatWriteSupported {
		return errors.New("signed managed compatibility evidence does not affirm the exact update and durability profile")
	}
	for _, seat := range intent.Seats {
		if seat.SeatID == intent.CanarySeatID && seat.ArtifactDigest != intent.OldArtifactDigest ||
			seat.ArtifactDigest != intent.OldArtifactDigest && seat.ArtifactDigest != intent.CandidateArtifactDigest {
			return errors.New("managed update canary must run the prior artifact and its peer the prior or candidate artifact")
		}
	}
	return nil
}

func (seat ManagedUpdateSeat) validate(intent ManagedUpdateIntent) error {
	if !entityid.Valid(seat.SeatID) || !knownRegion(seat.Region) || !strings.EqualFold(string(seat.Region), intent.Cell) ||
		!entityid.Valid(seat.MemberID) || !lowerHex(seat.Incarnation, 32) || allZeroHex(seat.Incarnation) ||
		!validLowerSHA256Digest(seat.TLSLeafSHA256) || !validLowerSHA256Digest(seat.RuntimeManifestDigest) ||
		!validToken(seat.HostNode) || seat.HostGeneration == 0 || seat.HostAttempt == 0 ||
		!validOCID(seat.OCIInstanceID, "instance") || !validToken(seat.OCIOwner) || seat.OCIFleetGeneration == 0 ||
		!entityid.Valid(seat.CreateKey) || !validOCID(seat.VolumeID, "volume") ||
		!validOCID(seat.AttachmentID, "volumeattachment") || seat.AttachmentETag == "" ||
		strings.ContainsAny(seat.AttachmentETag, "\r\n\x00") || !validManagedDevicePath(seat.AttachmentDevice) ||
		seat.DesiredGeneration == 0 || !validLowerSHA256Digest(seat.ArtifactDigest) {
		return errors.New("incomplete managed seat predecessor identity")
	}
	return nil
}

// Validate checks the persistent-format profile before it is signed into a
// managed update. Exact correspondence to the active placement is checked by
// the regional admission handler.
func (profile ManagedUpdateDurabilityProfile) Validate() error {
	if profile.SchemaVersion != ManagedUpdateSchemaVersion || !knownRegion(profile.Region) ||
		len(profile.Volumes) != 2 ||
		(profile.SQLSchemaBundleSHA256 != "" && !validLowerSHA256Digest(profile.SQLSchemaBundleSHA256)) ||
		!validLowerSHA256Digest(profile.LiveS3ConfigSHA256) ||
		!validLowerSHA256Digest(profile.LiveS3TargetSHA256) || profile.LiveS3Credential.Validate() != nil {
		return errors.New("incomplete managed durability profile")
	}
	if !slices.IsSortedFunc(profile.Volumes, func(left, right ManagedUpdateVolumeProfile) int {
		return strings.Compare(left.SeatID, right.SeatID)
	}) {
		return errors.New("managed durability volumes must be sorted by seat ID")
	}
	for index, volume := range profile.Volumes {
		if !entityid.Valid(volume.SeatID) || (index > 0 && profile.Volumes[index-1].SeatID == volume.SeatID) ||
			!validOCID(volume.VolumeID, "volume") || !validFilesystemUUID(volume.FileSystemUUID) ||
			volume.FileSystemType != "ext4" && volume.FileSystemType != "xfs" {
			return errors.New("invalid managed durability volume profile")
		}
	}
	if profile.LiveS3Credential.Validate() != nil {
		return errors.New("managed durability profile requires an exact ObjectDurable credential version")
	}
	return nil
}

// Digest returns the lower-case SHA-256 of the canonical selected profile.
func (profile ManagedUpdateDurabilityProfile) Digest() (string, error) {
	if err := profile.Validate(); err != nil {
		return "", err
	}
	encoded, err := protocol.EncodeJSON(profile)
	if err != nil {
		return "", err
	}
	digest := sha256.Sum256(encoded)
	return hex.EncodeToString(digest[:]), nil
}

// Digest returns the canonical SHA-256 used as the authority operation
// fingerprint and in receipts. Compatibility evidence signatures are part of
// the request bytes and therefore part of this digest.
func (intent ManagedUpdateIntent) Digest() (string, error) {
	if err := intent.Validate(); err != nil {
		return "", err
	}
	encoded, err := protocol.EncodeJSON(intent)
	if err != nil {
		return "", err
	}
	digest := sha256.Sum256(encoded)
	return hex.EncodeToString(digest[:]), nil
}

func validOCID(value, kind string) bool {
	prefix := "ocid1." + kind + "."
	return len(value) > len(prefix) && len(value) <= 255 && strings.HasPrefix(value, prefix) &&
		!strings.ContainsAny(value, " \t\r\n\x00")
}

func validManagedDevicePath(value string) bool {
	return len(value) <= 255 && filepath.IsAbs(value) && filepath.Clean(value) == value &&
		!strings.ContainsAny(value, " \t\r\n\x00")
}

update_reconcile_outcome.text:
func (controller *Controller) reconcileManagedUpdate(ctx context.Context, epoch uint64,
	intent Intent, seats []Seat, memberByID map[string]VersionedMemberState,
) (bool, error) {
	reader, ok := controller.fencer.(authority.ManagedUpdateReader)
	if !ok {
		return false, errors.New("placement authority lacks managed update history")
	}
	latest, err := reader.ReadManagedUpdate(ctx, intent.DatabaseID, intent.PartitionID)
	if errors.Is(err, authority.ErrNotFound) {
		return false, nil
	}
	if err != nil {
		return false, err
	}
	if latest.Kind != authority.MutationManagedUpdate || latest.Sequence == 0 || latest.OperationID == "" {
		return false, errors.New("managed update authority history is malformed")
	}
	var record authority.ManagedUpdateRecord
	if err := json.Unmarshal(latest.Payload, &record, json.RejectUnknownMembers(true)); err != nil ||
		record.Validate() != nil || record.OperationID != latest.OperationID ||
		record.DatabaseID != intent.DatabaseID || record.PartitionID != intent.PartitionID ||
		managedUpdatePhaseFromSubject(latest.SubjectKey) != record.Phase {
		return false, errors.New("managed update authority phase is corrupt")
	}
	if record.Phase == authority.ManagedUpdateHeld || record.Phase == authority.ManagedUpdateCanaryServing {
		return controller.reconcileManagedUpdateTerminal(ctx, epoch, intent, latest, record, memberByID)
	}
	if record.Phase != authority.ManagedUpdatePrepared {
		return false, errors.New("managed update authority phase is unsupported")
	}
	_, update, _, err := decodeManagedUpdateRequest(latest, controller.config.Cell)
	if err != nil || update.DatabaseID != intent.DatabaseID || update.PartitionID != intent.PartitionID ||
		update.PlacementGeneration != intent.Generation || update.PlacementPayloadDigest != intent.PayloadDigest() {
		return false, errors.New("prepared managed update no longer matches the active placement")
	}
	canary, exists := memberByID[record.CanarySeatID]
	if !exists {
		controller.hold(fmt.Sprintf("managed update %s has no durable canary seat", record.OperationID))
		return false, nil
	}
	state := canary.State
	current := state.ManagedRuntimeTarget
	if current.OperationID == record.OperationID {
		if current.AuthoritySequence != latest.Sequence || current.RequestSHA256 != record.SignedRequestSHA256 ||
			current.ArtifactDigest != record.CandidateArtifactDigest {
			controller.hold(fmt.Sprintf("member %s has a different durable managed canary target", state.MemberID))
		}
		return false, nil
	}
	if current.Phase == ManagedUpdateSeatPrepared {
		controller.hold(fmt.Sprintf("member %s has an unfinished managed canary target", state.MemberID))
		return false, nil
	}
	if err := controller.verifyManagedUpdateBaseline(ctx, update, record, epoch); err != nil {
		controller.hold(fmt.Sprintf("managed update %s baseline changed before its canary write: %v", record.OperationID, err))
		return false, nil
	}
	rollsBackHeld := managedUpdateRollsBackHeld(update, state)
	if state.Stage != StageServing && !rollsBackHeld || state.DesiredGeneration == 0 ||
		state.DesiredGeneration == ^uint64(0) || record.CanaryDesiredGeneration != state.DesiredGeneration+1 {
		controller.hold(fmt.Sprintf("member %s is not at the exact signed canary predecessor", state.MemberID))
		return false, nil
	}
	previousSource := ""
	if current.OperationID != "" {
		previousSource = current.SourceDigest
	}
	state.SchemaVersion = managedUpdateMemberStateSchemaVersion
	state.ManagedRuntimeTarget = ManagedRuntimeTarget{
		OperationID: record.OperationID, AuthoritySequence: latest.Sequence,
		RequestSHA256: record.SignedRequestSHA256, PreparedAt: controller.currentTime().UTC(),
		PlacementGeneration:    record.PlacementGeneration,
		PlacementPayloadDigest: record.PlacementPayloadDigest, CanarySeatID: record.CanarySeatID,
		PreviousDesiredGeneration: state.DesiredGeneration,
		PreviousArtifactDigest:    state.EffectiveRuntimeManifest().ArtifactDigest, PreviousSourceDigest: previousSource,
		DesiredGeneration: record.CanaryDesiredGeneration, ArtifactDigest: record.CandidateArtifactDigest,
		ManifestDigest: record.CandidateManifestDigest, SourceDigest: record.CandidateSourceDigest,
		Phase: ManagedUpdateSeatPrepared, RollbackOfHeld: rollsBackHeld,
	}
	state.DesiredGeneration = record.CanaryDesiredGeneration
	state.Stage = StagePreparedDesired
	state.OperationID = digestToken("u", state.DatabaseID, state.PartitionID, record.OperationID, state.MemberID, "prepared")
	if _, err := controller.persist(ctx, epoch, canary.Revision, state); err != nil {
		return false, err
	}
	return true, nil
}

func (controller *Controller) reconcileManagedUpdateTerminal(ctx context.Context, epoch uint64,
	active Intent, latest authority.LogEntry, terminal authority.ManagedUpdateRecord,
	memberByID map[string]VersionedMemberState,
) (bool, error) {
	reader, ok := controller.fencer.(authority.ManagedUpdateReader)
	if !ok {
		return false, errors.New("placement authority lacks exact managed update history")
	}
	history, err := reader.ReadManagedUpdateOperation(ctx, terminal.DatabaseID, terminal.PartitionID,
		terminal.OperationID)
	if err != nil {
		return false, err
	}
	if len(history) != 2 || history[1].Sequence != latest.Sequence ||
		managedUpdatePhaseFromSubject(history[0].SubjectKey) != authority.ManagedUpdatePrepared ||
		managedUpdatePhaseFromSubject(history[1].SubjectKey) != terminal.Phase {
		controller.hold(fmt.Sprintf("managed update %s terminal history cannot be reconciled safely", terminal.OperationID))
		return true, nil
	}
	prepared, update, _, err := decodeManagedUpdateRequest(history[0], controller.config.Cell)
	if err != nil {
		return false, err
	}
	verifiedTerminal, err := decodeManagedUpdatePhaseRecord(latest, prepared, terminal.Phase)
	if err != nil || verifiedTerminal.Outcome != terminal.Outcome ||
		terminal.Phase == authority.ManagedUpdateCanaryServing && terminal.Outcome != string(authority.ManagedUpdateCanaryServing) ||
		terminal.Phase == authority.ManagedUpdateHeld && terminal.Outcome != "candidate-reported-failure" &&
			terminal.Outcome != "candidate-proof-timeout" ||
		update.DatabaseID != active.DatabaseID || update.PartitionID != active.PartitionID ||
		update.PlacementGeneration != active.Generation || update.PlacementPayloadDigest != active.PayloadDigest() {
		controller.hold(fmt.Sprintf("managed update %s terminal record differs from its exact signed Prepare", terminal.OperationID))
		return true, nil
	}
	placementReader, ok := controller.fencer.(managedUpdatePlacementReader)
	if !ok {
		return false, errors.New("placement authority lacks immutable placement history")
	}
	placementEntry, err := placementReader.ReadPlacementIntent(ctx, update.DatabaseID, update.PartitionID)
	if err != nil {
		return false, err
	}
	currentIntent, err := DecodeCommittedIntent(placementEntry.Payload)
	if err != nil || placementEntry.Sequence != update.PlacementSequence ||
		currentIntent.Generation != update.PlacementGeneration ||
		currentIntent.PayloadDigest() != update.PlacementPayloadDigest ||
		currentIntent.DatabaseID != active.DatabaseID || currentIntent.PartitionID != active.PartitionID {
		controller.hold(fmt.Sprintf("managed update %s terminal outcome is not for the current immutable placement", terminal.OperationID))
		return true, nil
	}
	canary, exists := memberByID[update.CanarySeatID]
	if !exists || !managedUpdateSeatTargetMatches(update, history[0].Sequence, prepared, canary.State) {
		controller.hold(fmt.Sprintf("managed update %s terminal outcome has no exact prepared canary seat", terminal.OperationID))
		return true, nil
	}
	return controller.persistManagedUpdateSeatOutcome(ctx, epoch, currentIntent, update, history[0].Sequence,
		prepared, terminal, canary)
}

func (controller *Controller) persistManagedUpdateSeatOutcome(ctx context.Context, epoch uint64,
	active Intent, update ManagedUpdateIntent, preparedSequence uint64,
	prepared, terminal authority.ManagedUpdateRecord,
	canary VersionedMemberState,
) (bool, error) {
	if terminal.Phase != authority.ManagedUpdateHeld && terminal.Phase != authority.ManagedUpdateCanaryServing {
		return false, errors.New("managed update seat outcome is not terminal")
	}
	state := canary.State
	if !managedUpdateSeatTargetMatches(update, preparedSequence, prepared, state) {
		controller.hold(fmt.Sprintf("managed update %s terminal outcome has no exact prepared canary seat", terminal.OperationID))
		return true, nil
	}
	wantPhase := ManagedUpdateSeatHeld
	if terminal.Phase == authority.ManagedUpdateCanaryServing {
		wantPhase = ManagedUpdateSeatCanaryServing
	}
	target := state.ManagedRuntimeTarget
	if target.Phase == wantPhase && target.Outcome == terminal.Outcome {
		if terminal.Phase == authority.ManagedUpdateHeld &&
			(state.Stage == StagePreparedDesired || state.Stage == StageAwaitingHealthy) {
			controller.hold(fmt.Sprintf("managed update %s is durably held: %s", terminal.OperationID, terminal.Outcome))
			return true, nil
		}
		if terminal.Phase == authority.ManagedUpdateCanaryServing && state.Stage == StageServing {
			return false, nil
		}
		controller.hold(fmt.Sprintf("managed update %s terminal seat stage is inconsistent", terminal.OperationID))
		return true, nil
	}
	if target.Phase != ManagedUpdateSeatPrepared || target.Outcome != "" ||
		terminal.Phase == authority.ManagedUpdateCanaryServing && state.Stage != StageAwaitingHealthy ||
		terminal.Phase == authority.ManagedUpdateHeld && state.Stage != StagePreparedDesired &&
			state.Stage != StageAwaitingHealthy {
		controller.hold(fmt.Sprintf("managed update %s terminal outcome cannot replace the current canary seat phase", terminal.OperationID))
		return true, nil
	}
	target.Phase = wantPhase
	target.Outcome = terminal.Outcome
	state.ManagedRuntimeTarget = target
	if terminal.Phase == authority.ManagedUpdateCanaryServing {
		state.Stage = StageServing
		state.OperationID = memberOperationID(active, state.MemberID, state.HostAttempt, "serving")
	} else {
		state.OperationID = digestToken("u", state.DatabaseID, state.PartitionID,
			terminal.OperationID, state.MemberID, "held")
	}
	if _, err := controller.persist(ctx, epoch, canary.Revision, state); err != nil {
		return false, err
	}
	if terminal.Phase == authority.ManagedUpdateHeld {
		controller.hold(fmt.Sprintf("managed update %s is durably held: %s", terminal.OperationID, terminal.Outcome))
	}
	return true, nil
}

func managedUpdateSeatTargetMatches(update ManagedUpdateIntent, preparedSequence uint64,
	prepared authority.ManagedUpdateRecord, state MemberState,
) bool {
	target := state.ManagedRuntimeTarget
	if state.SchemaVersion != managedUpdateMemberStateSchemaVersion || target.OperationID != prepared.OperationID ||
		target.AuthoritySequence != preparedSequence || target.RequestSHA256 != prepared.SignedRequestSHA256 ||
		target.PreparedAt.IsZero() || target.PreparedAt.Location() != time.UTC ||
		target.PlacementGeneration != update.PlacementGeneration ||
		target.PlacementPayloadDigest != update.PlacementPayloadDigest ||
		target.CanarySeatID != update.CanarySeatID ||
		target.PreviousArtifactDigest != update.OldArtifactDigest ||
		target.DesiredGeneration != update.CanaryDesiredGeneration ||
		target.ArtifactDigest != update.CandidateArtifactDigest ||
		target.ManifestDigest != update.CandidateManifestDigest || target.SourceDigest != update.CandidateSourceDigest {
		return false
	}
	seatIndex := slices.IndexFunc(update.Seats, func(seat ManagedUpdateSeat) bool {
		return seat.SeatID == update.CanarySeatID
	})
	if seatIndex < 0 {
		return false
	}
	if update.Seats[seatIndex].DesiredGeneration != target.PreviousDesiredGeneration {
		return false
	}
	return managedUpdateSeatMatches(update.Seats[seatIndex], state.PredecessorState())
}

func decodeManagedUpdatePhaseRecord(entry authority.LogEntry, prepared authority.ManagedUpdateRecord,
	want authority.ManagedUpdatePhase,
) (authority.ManagedUpdateRecord, error) {
	var record authority.ManagedUpdateRecord
	if entry.Kind != authority.MutationManagedUpdate || entry.OperationID != prepared.OperationID ||
		managedUpdatePhaseFromSubject(entry.SubjectKey) != want {
		return record, errors.New("managed update terminal phase has a mismatched authority identity")
	}
	if err := json.Unmarshal(entry.Payload, &record, json.RejectUnknownMembers(true)); err != nil {
		return record, err
	}
	canonical, err := json.Marshal(record, json.Deterministic(true))
	if err != nil || !bytes.Equal(canonical, entry.Payload) || record.Validate() != nil ||
		record.Phase != want || !prepared.SameIdentity(record) {
		return record, errors.New("managed update terminal phase differs from its signed Prepare identity")
	}
	return record, nil
}

func (controller *Controller) commitManagedUpdateOutcome(ctx context.Context, epoch uint64,
	state MemberState, phase authority.ManagedUpdatePhase, outcome string,
	verify func(context.Context, ManagedUpdateIntent, authority.ManagedUpdateRecord) error,
) (uint64, error) {
	if err := controller.guard(ctx, epoch); err != nil {
		return 0, err
	}
	reader, ok := controller.fencer.(authority.ManagedUpdateStore)
	if !ok {
		return 0, errors.New("placement authority cannot commit a managed update outcome")
	}
	entries, err := reader.ReadManagedUpdateOperation(ctx, state.DatabaseID, state.PartitionID,
		state.ManagedRuntimeTarget.OperationID)
	if err != nil {
		return 0, err
	}
	var preparedEntry authority.LogEntry
	for _, entry := range entries {
		if managedUpdatePhaseFromSubject(entry.SubjectKey) == authority.ManagedUpdatePrepared {
			preparedEntry = entry
			break
		}
	}
	if preparedEntry.Sequence != state.ManagedRuntimeTarget.AuthoritySequence {
		return 0, authority.ErrInvalidTransition
	}
	prepared, update, _, err := decodeManagedUpdateRequest(preparedEntry, controller.config.Cell)
	if err != nil || prepared.OperationID != state.ManagedRuntimeTarget.OperationID ||
		prepared.SignedRequestSHA256 != state.ManagedRuntimeTarget.RequestSHA256 ||
		update.CanarySeatID != state.MemberID ||
		state.ManagedRuntimeTarget.AuthoritySequence != preparedEntry.Sequence {
		return 0, authority.ErrInvalidTransition
	}
	record := prepared
	record.Phase = phase
	record.Outcome = outcome
	return reader.CommitManagedUpdate(ctx, epoch, record, preparedEntry.Sequence,
		func(verifyCtx context.Context) error {
			if _, err := controller.store.ReadTerminalIntent(verifyCtx, state.DatabaseID, state.PartitionID); err == nil {
				return authority.ErrFenced
			} else if !errors.Is(err, authority.ErrNotFound) {
				return err
			}
			if verify == nil {
				return nil
			}
			return verify(verifyCtx, update, prepared)
		})
}

func managedUpdateCanaryTiming(target ManagedRuntimeTarget, now time.Time) (timedOut, clockValid bool) {
	if target.PreparedAt.IsZero() || target.PreparedAt.Location() != time.UTC {
		return false, false
	}
	now = now.UTC()
	if now.Before(target.PreparedAt) {
		return false, false
	}
	deadline := target.PreparedAt.Add(managedUpdateCanaryProofTimeout)
	if !deadline.After(target.PreparedAt) {
		return false, false
	}
	return !now.Before(deadline), true
}

func (controller *Controller) holdTimedOutManagedCanary(ctx context.Context, epoch uint64,
	intent Intent, versioned VersionedMemberState,
) (bool, error) {
	state := versioned.State
	target := state.ManagedRuntimeTarget
	if target.OperationID == "" {
		return false, nil
	}
	if target.Phase != ManagedUpdateSeatPrepared {
		controller.hold(fmt.Sprintf("managed update %s has an unreconciled canary phase", target.OperationID))
		return true, nil
	}
	if target.PlacementGeneration != intent.Generation || target.PlacementPayloadDigest != intent.PayloadDigest() {
		controller.hold(fmt.Sprintf("managed update %s no longer matches its immutable placement", target.OperationID))
		return true, nil
	}
	timedOut, clockValid := managedUpdateCanaryTiming(target, controller.currentTime())
	if !clockValid {
		controller.hold(fmt.Sprintf("managed update %s has a future or invalid canary preparation clock", target.OperationID))
		return true, nil
	}
	if !timedOut {
		return false, nil
	}
	const outcome = "candidate-proof-timeout"
	if _, err := controller.commitManagedUpdateOutcome(ctx, epoch, state, authority.ManagedUpdateHeld, outcome,
		func(verifyCtx context.Context, update ManagedUpdateIntent, prepared authority.ManagedUpdateRecord) error {
			return controller.verifyManagedCanaryTimeoutAtAuthorityCommit(verifyCtx, epoch, update, prepared, versioned)
		}); err != nil {
		return false, err
	}
	target.Phase = ManagedUpdateSeatHeld
	target.Outcome = outcome
	state.ManagedRuntimeTarget = target
	state.OperationID = digestToken("u", state.DatabaseID, state.PartitionID,
		target.OperationID, state.MemberID, "held")
	if _, err := controller.persist(ctx, epoch, versioned.Revision, state); err != nil {
		return false, err
	}
	controller.hold(fmt.Sprintf("managed update %s is durably held after its canary proof deadline", target.OperationID))
	return true, nil
}

update_timeout_verifier.text:
func (controller *Controller) verifyManagedCanaryTimeoutAtAuthorityCommit(ctx context.Context, epoch uint64,
	update ManagedUpdateIntent, prepared authority.ManagedUpdateRecord, expected VersionedMemberState,
) error {
	// CommitManagedUpdate holds the final authority fence throughout this check.
	if _, err := controller.store.ReadTerminalIntent(ctx, update.DatabaseID, update.PartitionID); err == nil {
		return authority.ErrFenced
	} else if !errors.Is(err, authority.ErrNotFound) {
		return err
	}
	placementReader, ok := controller.fencer.(managedUpdatePlacementReader)
	if !ok {
		return errors.New("managed canary timeout verifier lacks placement history")
	}
	placementEntry, err := placementReader.ReadPlacementIntent(ctx, update.DatabaseID, update.PartitionID)
	if err != nil {
		return err
	}
	currentIntent, err := DecodeCommittedIntent(placementEntry.Payload)
	if err != nil || placementEntry.Sequence != update.PlacementSequence ||
		currentIntent.Generation != update.PlacementGeneration ||
		currentIntent.PayloadDigest() != update.PlacementPayloadDigest {
		return errors.New("managed canary timeout is not for the current immutable placement")
	}
	current, err := controller.store.ReadMember(ctx, update.DatabaseID, update.PartitionID,
		expected.State.MemberID)
	if err != nil || current.Revision != expected.Revision || !reflect.DeepEqual(current.State, expected.State) ||
		current.State.Stage != StagePreparedDesired && current.State.Stage != StageAwaitingHealthy ||
		current.State.ManagedRuntimeTarget.Phase != ManagedUpdateSeatPrepared ||
		!managedUpdateSeatTargetMatches(update, expected.State.ManagedRuntimeTarget.AuthoritySequence,
			prepared, current.State) {
		return errors.New("managed canary seat changed before its timeout outcome commit")
	}
	timedOut, clockValid := managedUpdateCanaryTiming(current.State.ManagedRuntimeTarget, controller.currentTime())
	if !clockValid || !timedOut {
		return errors.New("managed canary timeout has not reached its durable deadline")
	}
	return nil
}

update_decode.text:
func decodeManagedUpdateRequest(
	entry authority.LogEntry,
	cell string,
) (authority.ManagedUpdateRecord, ManagedUpdateIntent, protocol.Envelope, error) {
	var record authority.ManagedUpdateRecord
	if err := json.Unmarshal(entry.Payload, &record, json.RejectUnknownMembers(true)); err != nil {
		return record, ManagedUpdateIntent{}, protocol.Envelope{}, err
	}
	wantSubject := strings.Join([]string{record.DatabaseID, record.PartitionID,
		record.OperationID, string(record.Phase)}, ".")
	if record.Validate() != nil || record.Cell != cell || wantSubject != entry.SubjectKey ||
		record.OperationID != entry.OperationID || record.Phase != authority.ManagedUpdatePrepared {
		return record, ManagedUpdateIntent{}, protocol.Envelope{}, errors.New("managed update Prepare record is malformed")
	}
	canonicalRecord, err := json.Marshal(record, json.Deterministic(true))
	if err != nil || !bytes.Equal(canonicalRecord, entry.Payload) {
		return record, ManagedUpdateIntent{}, protocol.Envelope{}, errors.New("managed update Prepare record is not canonical")
	}
	var envelope protocol.Envelope
	if err := protocol.DecodeStrict(record.SignedRequest, &envelope, protocol.MaxPayloadBytes+4096); err != nil {
		return record, ManagedUpdateIntent{}, protocol.Envelope{}, err
	}
	var intent ManagedUpdateIntent
	if err := protocol.DecodeStrict(envelope.Payload, &intent, protocol.MaxPayloadBytes); err != nil {
		return record, intent, envelope, err
	}
	canonical, err := protocol.EncodeJSON(intent)
	if err != nil || !bytes.Equal(canonical, envelope.Payload) || intent.Validate() != nil ||
		envelope.Kind != ManagedUpdateEnvelopeKind || !managedUpdateEnvelopeRegionMatches(envelope, cell) ||
		envelope.OperationID != record.OperationID || envelope.Generation != intent.CanaryDesiredGeneration ||
		envelope.Epoch != intent.AuthorityEpoch || entry.Epoch != envelope.Epoch ||
		intent.Cell != record.Cell || intent.DatabaseID != record.DatabaseID ||
		intent.PartitionID != record.PartitionID || intent.OperationID != record.OperationID ||
		intent.PlacementGeneration != record.PlacementGeneration ||
		intent.PlacementPayloadDigest != record.PlacementPayloadDigest ||
		intent.PlacementSequence != record.PlacementSequence || intent.CanarySeatID != record.CanarySeatID ||
		intent.CanaryDesiredGeneration != record.CanaryDesiredGeneration ||
		intent.OldArtifactDigest != record.OldArtifactDigest ||
		intent.CandidateArtifactDigest != record.CandidateArtifactDigest ||
		intent.CandidateManifestDigest != record.CandidateManifestDigest ||
		intent.CandidateSourceDigest != record.CandidateSourceDigest {
		return record, intent, envelope, errors.New("managed update signed request differs from its immutable authority record")
	}
	return record, intent, envelope, nil
}

func managedUpdateEnvelopeRegionMatches(envelope protocol.Envelope, cell string) bool {
	canonicalCell, err := protocol.CanonicalRegion(cell)
	return err == nil && envelope.Region == canonicalCell
}

func managedUpdatePhaseFromSubject(subjectKey string) authority.ManagedUpdatePhase {
	_, phase, ok := strings.CutLast(subjectKey, ".")
	if !ok {
		return ""
	}
	return authority.ManagedUpdatePhase(phase)
}

