func ManagedUpdateSeatFor(state MemberState, owner string, fleetGeneration uint64) ManagedUpdateSeat {
	return ManagedUpdateSeat{
		SeatID: state.MemberID, Region: state.Region, MemberID: state.CanonicalRosterRow.MemberID,
		Incarnation: state.CanonicalRosterRow.Incarnation, TLSLeafSHA256: state.CanonicalRosterRow.TLSLeafSHA256,
		RuntimeManifestDigest: state.RuntimeManifestDigest, HostNode: state.HostNode,
		HostGeneration: state.HostGeneration, HostAttempt: state.HostAttempt,
		OCIInstanceID: state.InstanceID, OCIOwner: owner, OCIFleetGeneration: fleetGeneration,
		CreateKey: state.CreateKey, VolumeID: state.VolumeID, AttachmentID: state.AttachmentID,
		AttachmentETag: state.AttachmentETag, AttachmentDevice: state.AttachmentDevice,
		DesiredGeneration: state.DesiredGeneration, ArtifactDigest: state.EffectiveRuntimeManifest().ArtifactDigest,
	}
}

intent_validation.text:
func (manifest RuntimeManifest) Validate() error {

	if !knownRegion(manifest.Region) || !entityid.Valid(manifest.SeatID) ||
		!validLowerSHA256Digest(manifest.ArtifactDigest) || !validLowerSHA256Digest(manifest.SourceDigest) ||
		!filepath.IsAbs(manifest.ManagedRuntimeRoot) || filepath.Clean(manifest.ManagedRuntimeRoot) != manifest.ManagedRuntimeRoot ||
		manifest.ManagedRuntimeRoot == "/" || len(manifest.ManagedRuntimeRoot) > 54 ||
		!validFilesystemUUID(manifest.FileSystemUUID) ||
		manifest.FileSystemType != "ext4" && manifest.FileSystemType != "xfs" ||
		!validLowerSHA256Digest(manifest.TrustedKeySHA256) ||
		!validLowerSHA256Digest(manifest.ServerCertificateSHA256) ||
		!validLowerSHA256Digest(manifest.ServerPrivateKeySHA256) ||
		!validLowerSHA256Digest(manifest.ClientCARootsSHA256) ||
		!validPrivateIPv4Endpoint(manifest.ReplicationListenAddress) {
		return fmt.Errorf("%w: incomplete runtime manifest", ErrInvalidIntent)
	}
	peer := manifest.ReplicationPeerMemberID != "" || manifest.ReplicationPeerAddress != "" || manifest.ReplicationServerCASHA256 != ""
	if peer && (!entityid.Valid(manifest.ReplicationPeerMemberID) ||
		!validPrivateIPv4Endpoint(manifest.ReplicationPeerAddress) ||
		!validLowerSHA256Digest(manifest.ReplicationServerCASHA256)) {
		return fmt.Errorf("%w: incomplete runtime peer triple", ErrInvalidIntent)
	}
	if !validLowerSHA256Digest(manifest.ClientManagedMaterialManifestSHA256) || !peer {
		return fmt.Errorf("%w: schema-5 managed HTTPS requires a pinned client material manifest and outbound peer", ErrInvalidIntent)
	}
	if !validLowerSHA256Digest(manifest.LiveS3ConfigSHA256) ||
		!validLowerSHA256Digest(manifest.LiveS3TargetSHA256) || manifest.LiveS3Credential.Validate() != nil {
		return fmt.Errorf("%w: managed ObjectDurable target or credential pin is incomplete", ErrInvalidIntent)
	}
	if manifest.BackupManifestSHA256 != "" {
		if !validLowerSHA256Digest(manifest.BackupManifestSHA256) ||
			!validLowerSHA256Digest(manifest.BackupS3ConfigSHA256) ||
			!validLowerSHA256Digest(manifest.BackupS3TargetSHA256) ||
			!validLowerSHA256Digest(manifest.BackupS3CredentialSHA256) ||
			!validLowerSHA256Digest(manifest.BackupDataKeySHA256) ||
			manifest.BackupS3TargetSHA256 == manifest.LiveS3TargetSHA256 ||
			manifest.BackupOwner && (manifest.BackupS3Credential.Validate() != nil ||
				manifest.BackupDataKey.Validate() != nil ||
				manifest.BackupS3Credential.SecretOCID == manifest.LiveS3Credential.SecretOCID ||
				manifest.BackupS3Credential.SecretOCID == manifest.BackupDataKey.SecretOCID) ||
			!manifest.BackupOwner && (manifest.BackupS3Credential != (oci.SecretVersionReference{}) ||
				manifest.BackupDataKey != (oci.SecretVersionReference{})) {
			return fmt.Errorf("%w: managed backup material pins are incomplete", ErrInvalidIntent)
		}
	} else if manifest.BackupS3ConfigSHA256 != "" || manifest.BackupS3TargetSHA256 != "" ||
		manifest.BackupS3CredentialSHA256 != "" || manifest.BackupDataKeySHA256 != "" ||
		manifest.BackupOwner || manifest.BackupS3Credential != (oci.SecretVersionReference{}) ||
		manifest.BackupDataKey != (oci.SecretVersionReference{}) {
		return fmt.Errorf("%w: partial managed backup material pins", ErrInvalidIntent)
	}
	if manifest.SQLSchemaBundleSHA256 != "" && !validLowerSHA256Digest(manifest.SQLSchemaBundleSHA256) {
		return fmt.Errorf("%w: invalid SQL schema bundle pin", ErrInvalidIntent)
	}
	return nil
}

func (manifest RuntimeManifest) Digest() (string, error) {

	if err := manifest.Validate(); err != nil {
		return "", err
	}
	encoded, err := protocol.EncodeJSON(manifest)
	if err != nil {
		return "", err
	}
	digest := sha256.Sum256(encoded)
	return hex.EncodeToString(digest[:]), nil
}

// ComputeTuple is the explicit Flex compute shape pinned by a signed profile.
// OCPUs and memory are whole provider units; fractional values are not accepted.
type ComputeTuple struct {
	Shape       string `json:"shape"`
	WholeOCPUs  uint32 `json:"whole_ocpus"`
	MemoryInGBs uint32 `json:"memory_in_gbs"`
}

// ManagedHostProfile pins one selected region's OCI compute tuple and guest
// memory contract. The byte values are supplied by the operator and are never
// inferred or defaulted by placement admission.
type ManagedHostProfile struct {
	Region                 oci.Region   `json:"region"`
	Compute                ComputeTuple `json:"compute"`
	ProcessMemoryBytes     uint64       `json:"process_memory_bytes"`
	MemoryHeadroomBytes    uint64       `json:"memory_headroom_bytes"`
	CgroupMemoryMaxBytes   uint64       `json:"cgroup_memory_max_bytes"`
	SystemReserveBytes     uint64       `json:"system_reserve_bytes"`
	AllocatableMemoryBytes uint64       `json:"allocatable_memory_bytes"`
}

// ProfileDigest returns the lower-case SHA-256 of deterministic JSON for the
// entire region profile, including its region, compute tuple and all byte
// limits. Placement generation is pinned separately by Intent.Generation.
func (profile ManagedHostProfile) ProfileDigest() (string, error) {
	if err := profile.Validate(); err != nil {
		return "", err
	}
	encoded, err := protocol.EncodeJSON(profile)
	if err != nil {
		return "", fmt.Errorf("encode managed host profile: %w", err)
	}
	digest := sha256.Sum256(encoded)
	return hex.EncodeToString(digest[:]), nil
}

func (profile ManagedHostProfile) Validate() error {
	if !knownRegion(profile.Region) || !validComputeShape(profile.Compute.Shape) ||
		profile.Compute.WholeOCPUs == 0 || profile.Compute.MemoryInGBs == 0 {
		return fmt.Errorf("%w: managed profile region or compute tuple", ErrInvalidIntent)
	}
	values := [...]uint64{
		profile.ProcessMemoryBytes, profile.MemoryHeadroomBytes, profile.CgroupMemoryMaxBytes,
		profile.SystemReserveBytes, profile.AllocatableMemoryBytes,
	}
	for _, value := range values {
		if value == 0 || value > maxManagedMemoryByteValue || value%managedMemoryPageBytes != 0 {
			return fmt.Errorf("%w: memory limits must be positive, signed-range, page-aligned byte values", ErrInvalidIntent)
		}
	}
	minimumHeadroom := max(managedMemoryGiB, profile.ProcessMemoryBytes/4)
	// MemoryInGBs is uint32, so this exact multiplication stays below 2^62.
	// GiB is the conservative upper bound whether the SDK's GB means decimal
	// or binary units; the host still verifies actual guest capacity.
	nominalMemoryBytes := uint64(profile.Compute.MemoryInGBs) * managedMemoryGiB
	if profile.ProcessMemoryBytes < 4*managedMemoryGiB || profile.MemoryHeadroomBytes < minimumHeadroom ||
		profile.MemoryHeadroomBytes >= profile.ProcessMemoryBytes ||
		profile.ProcessMemoryBytes > profile.CgroupMemoryMaxBytes ||
		profile.CgroupMemoryMaxBytes > profile.AllocatableMemoryBytes ||
		profile.SystemReserveBytes > maxManagedMemoryByteValue-profile.AllocatableMemoryBytes ||
		profile.AllocatableMemoryBytes > nominalMemoryBytes ||
		profile.SystemReserveBytes > nominalMemoryBytes-profile.AllocatableMemoryBytes {
		return fmt.Errorf("%w: managed process, headroom, cgroup, allocatable memory and reserve bounds", ErrInvalidIntent)
	}
	return nil
}

func (intent Intent) Validate() error {
	if intent.SchemaVersion != IntentSchemaVersion ||
		!entityid.Valid(intent.DatabaseID) ||
		!entityid.Valid(intent.PartitionID) || intent.Generation == 0 ||
		len(intent.ActiveRegions) < 1 || len(intent.ActiveRegions) > len(regionsInOrder) {
		return fmt.Errorf("%w: schema, identity, generation or region count", ErrInvalidIntent)
	}
	for index, region := range intent.ActiveRegions {
		if !knownRegion(region) {
			return fmt.Errorf("%w: unsupported region %q", ErrInvalidIntent, region)
		}
		if slices.Contains(intent.ActiveRegions[:index], region) {
			return fmt.Errorf("%w: repeated region %q", ErrInvalidIntent, region)
		}
	}
	if !canonicalRegions(intent.ActiveRegions) || len(intent.ManagedHostProfiles) != len(intent.ActiveRegions) {
		return fmt.Errorf("%w: managed profiles must exactly cover canonically ordered selected regions", ErrInvalidIntent)
	}
	for index, profile := range intent.ManagedHostProfiles {
		if profile.Region != intent.ActiveRegions[index] {
			return fmt.Errorf("%w: managed profiles are missing, foreign or out of canonical order", ErrInvalidIntent)
		}
		if err := profile.Validate(); err != nil {
			return err
		}
	}
	if err := intent.CanonicalRoster.Validate(intent.ActiveRegions); err != nil {
		return err
	}
	if len(intent.RuntimeManifests) != len(intent.CanonicalRoster.Rows) {
		return fmt.Errorf("%w: runtime manifests must cover every canonical roster seat", ErrInvalidIntent)
	}
	uuids := make(map[string]struct{}, len(intent.RuntimeManifests))
	for index, manifest := range intent.RuntimeManifests {
		row := intent.CanonicalRoster.Rows[index]
		if err := manifest.Validate(); err != nil {
			return err
		}
		if manifest.Region != row.Region || manifest.SeatID != row.SeatID ||
			manifest.TrustedKeySHA256 != intent.CanonicalRoster.Authority.TrustedKeySHA256 ||
			manifest.ReplicationPeerMemberID == row.MemberID {
			return fmt.Errorf("%w: runtime manifest does not match canonical roster seat", ErrInvalidIntent)
		}
		if manifest.ReplicationPeerMemberID != "" && !slices.ContainsFunc(intent.CanonicalRoster.Rows, func(peer CanonicalRosterRow) bool {
			return peer.MemberID == manifest.ReplicationPeerMemberID
		}) {
			return fmt.Errorf("%w: runtime peer is outside the signed roster", ErrInvalidIntent)
		}
		if _, exists := uuids[manifest.FileSystemUUID]; exists {
			return fmt.Errorf("%w: duplicate runtime filesystem UUID", ErrInvalidIntent)
		}
		uuids[manifest.FileSystemUUID] = struct{}{}
	}
	return nil
}

// ValidateForAdmission limits newly signed managed placements to schema 5.
// Only the current schema is accepted.
func (intent Intent) ValidateForAdmission() error {
	if intent.SchemaVersion != IntentSchemaVersion {
		return fmt.Errorf("%w: schema %d is historical and cannot authorize a new managed placement", ErrInvalidIntent, intent.SchemaVersion)
	}
	return intent.Validate()
}

func (roster CanonicalRoster) isZero() bool {
	return roster.ClusterID == "" && roster.TenantID == "" && roster.DatabaseID == "" &&
		roster.ShardID == 0 && roster.Authority == (AuthorityReference{}) && len(roster.Rows) == 0
}

func (roster CanonicalRoster) Validate(activeRegions []oci.Region) error {

	if !lowerHex(roster.ClusterID, 32) || allZeroHex(roster.ClusterID) ||
		!entityid.Valid(roster.TenantID) || !entityid.Valid(roster.DatabaseID) ||
		roster.ShardID == 0 || roster.Authority.Validate() != nil ||
		len(roster.Rows) != len(activeRegions)*2 {
		return fmt.Errorf("%w: canonical roster shared scope or row count", ErrInvalidIntent)
	}

	memberIDs := make(map[string]struct{}, len(roster.Rows))
	tlsLeafHashes := make(map[string]struct{}, len(roster.Rows))
	serverNames := make(map[string]struct{}, len(roster.Rows))
	failureDomains := make(map[oci.Region]string, len(activeRegions))
	for index, row := range roster.Rows {
		region := activeRegions[index/2]
		seatID := permanentMember(region)
		if index%2 == 1 {
			seatID = elasticMember(region)
		}
		if row.Region != region || row.SeatID != seatID || !validFailureDomain(row.FailureDomain) ||
			!entityid.Valid(row.MemberID) || !lowerHex(row.Incarnation, 32) || allZeroHex(row.Incarnation) ||
			!validLowerSHA256Digest(row.TLSLeafSHA256) || !validServerName(row.ServerName) {
			return fmt.Errorf("%w: invalid or noncanonical row %d in TerraBase member roster", ErrInvalidIntent, index)
		}
		if _, exists := memberIDs[row.MemberID]; exists {
			return fmt.Errorf("%w: repeated TerraBase member ID %q", ErrInvalidIntent, row.MemberID)
		}
		if _, exists := tlsLeafHashes[row.TLSLeafSHA256]; exists {
			return fmt.Errorf("%w: repeated TerraBase TLS leaf hash", ErrInvalidIntent)
		}
		if _, exists := serverNames[row.ServerName]; exists {
			return fmt.Errorf("%w: repeated TerraBase member server name %q", ErrInvalidIntent, row.ServerName)
		}
		if index%2 == 0 {
			failureDomains[region] = row.FailureDomain
		} else if failureDomains[region] == row.FailureDomain {
			return fmt.Errorf("%w: TerraBase members in region %s share a failure domain", ErrInvalidIntent, region)
		}
		memberIDs[row.MemberID] = struct{}{}
		tlsLeafHashes[row.TLSLeafSHA256] = struct{}{}
		serverNames[row.ServerName] = struct{}{}
	}
	return nil
}

func (authority AuthorityReference) Validate() error {
	if authority.Version != 2 || authority.Epoch == 0 ||
		!validLowerSHA256Digest(authority.ConfigurationID) || allZeroHex(authority.ConfigurationID) ||
		!validLowerSHA256Digest(authority.CertificateSHA256) || !validLowerSHA256Digest(authority.TrustedKeySHA256) {
		return fmt.Errorf("%w: invalid TerraBase authority reference", ErrInvalidIntent)
	}
	return nil
}

// CanonicalRosterDigest returns SHA-256 over deterministic canonical JSON for
// the roster. It does not verify signatures or the referenced certificate.
func (intent Intent) CanonicalRosterDigest() (string, error) {
	if err := intent.ValidateForAdmission(); err != nil {
		return "", err
	}
	encoded, err := protocol.EncodeJSON(intent.CanonicalRoster)
	if err != nil {
		return "", fmt.Errorf("encode canonical TerraBase roster: %w", err)
	}
	digest := sha256.Sum256(encoded)
	return hex.EncodeToString(digest[:]), nil
}

// RosterRowForSeat finds the signed row for one exact Go placement seat and
// checks its configured region and failure domain.
func (intent Intent) RosterRowForSeat(seat Seat) (CanonicalRosterRow, error) {
	if err := intent.ValidateForAdmission(); err != nil {
		return CanonicalRosterRow{}, err
	}
	for _, row := range intent.CanonicalRoster.Rows {
		if row.Region != seat.Region || row.SeatID != seat.MemberID {
			continue
		}
		if row.FailureDomain != seat.FailureDomain || seatIDForKind(row.Region, seat.Kind) != seat.MemberID {
			return CanonicalRosterRow{}, fmt.Errorf("%w: roster row does not match the configured placement seat", ErrInvalidIntent)
		}
		return row, nil
	}
	return CanonicalRosterRow{}, fmt.Errorf("%w: no canonical roster row for region %s seat %s", ErrInvalidIntent, seat.Region, seat.MemberID)
}

func seatIDForKind(region oci.Region, kind MemberKind) string {
	switch kind {
	case MemberPermanent:
		return permanentMember(region)
	case MemberElastic:
		return elasticMember(region)
	default:
		return ""
	}
}

func canonicalTerraBaseID(value string) bool { return entityid.Valid(value) }

func lowerHex(value string, length int) bool {
	if len(value) != length {
		return false
	}
	for index := range len(value) {
		character := value[index]
		if character < '0' || character > '9' {
			if character < 'a' || character > 'f' {
				return false
			}
		}
	}
	return true
}

func allZeroHex(value string) bool {
	for index := range len(value) {
		if value[index] != '0' {
			return false
		}
	}
	return true
}

func validFailureDomain(value string) bool {
	if len(value) < 1 || len(value) > 64 {
		return false
	}
	for index := range len(value) {
		character := value[index]
		if character >= 'a' && character <= 'z' || character >= 'A' && character <= 'Z' ||
			character >= '0' && character <= '9' || character == '.' || character == '_' || character == '-' {
			continue
		}
		return false
	}
	return true
}

func validServerName(value string) bool {
	if len(value) < 1 || len(value) > 253 {
		return false
	}
	for label := range strings.SplitSeq(value, ".") {
		if len(label) < 1 || len(label) > 63 || label[0] == '-' || label[len(label)-1] == '-' {
			return false
		}
		for index := range len(label) {
			character := label[index]
			if character >= 'a' && character <= 'z' || character >= '0' && character <= '9' || character == '-' {
				continue
			}
			return false
		}
	}
	return true
}

// ManagedHostProfile returns the exact admitted region profile.
func (intent Intent) ManagedHostProfile(region oci.Region) (ManagedHostProfile, error) {
	if err := intent.ValidateForAdmission(); err != nil {
		return ManagedHostProfile{}, err
	}
	index := slices.IndexFunc(intent.ManagedHostProfiles, func(profile ManagedHostProfile) bool { return profile.Region == region })
	if index < 0 {
		return ManagedHostProfile{}, fmt.Errorf("%w: region %q is not selected", ErrInvalidIntent, region)
	}
	return intent.ManagedHostProfiles[index], nil
}

// RuntimeManifestForSeat returns the exact operator-signed runtime contract.
func (intent Intent) RuntimeManifestForSeat(seat Seat) (RuntimeManifest, error) {
	if err := intent.ValidateForAdmission(); err != nil {
		return RuntimeManifest{}, err
	}
	for _, manifest := range intent.RuntimeManifests {
		if manifest.Region == seat.Region && manifest.SeatID == seat.MemberID {
			return manifest, nil
		}
	}
	return RuntimeManifest{}, fmt.Errorf("%w: no runtime manifest for seat %s/%s", ErrInvalidIntent, seat.Region, seat.MemberID)
}

// ProfileDigest returns the verified profile digest for one selected region.
func (intent Intent) ProfileDigest(region oci.Region) (string, error) {
	profile, err := intent.ManagedHostProfile(region)
	if err != nil {
		return "", err
	}
	return profile.ProfileDigest()
}

// PayloadDigest exposes the exact canonical payload digest attached by
// DecodeCommittedIntent after it reads the operator-signed ordered log.
func (intent Intent) PayloadDigest() string { return intent.committedPayloadSHA }

// OperationID is stable across regional log consumers and binds one admitted
// database/partition generation without depending on lease history.
func (intent Intent) OperationID() string {
	return entityid.Derive("placement-intent", intent.DatabaseID, intent.PartitionID, fmt.Sprint(intent.Generation))
}

// DecodeCommittedIntent validates canonical bytes returned from the ordered
// authority log and attaches their exact payload digest. It accepts schema 1
// only so callers can hold historical records; it does not make them eligible
// for a new managed placement.
func DecodeCommittedIntent(payload []byte) (Intent, error) {
	var intent Intent
	if err := protocol.DecodeStrict(payload, &intent, maxIntentPayloadBytes); err != nil {
		return Intent{}, fmt.Errorf("%w: decode committed placement intent: %v", ErrInvalidIntent, err)
	}
	if err := intent.Validate(); err != nil {
		return Intent{}, err
	}
	canonical, err := protocol.EncodeJSON(intent)
	if err != nil {
		return Intent{}, fmt.Errorf("%w: encode committed placement intent: %v", ErrInvalidIntent, err)
	}
	if !bytes.Equal(canonical, payload) {
		return Intent{}, fmt.Errorf("%w: committed placement intent is not canonical JSON", ErrInvalidIntent)
	}
	digest := sha256.Sum256(payload)
	intent.committedPayloadSHA = hex.EncodeToString(digest[:])
	return intent, nil
}

intent_seats.text:
func DesiredSeats(intent Intent, faultDomains map[oci.Region][]string) ([]Seat, error) {
	if err := intent.Validate(); err != nil {
		return nil, err
	}
	selected := make(map[oci.Region]struct{}, len(intent.ActiveRegions))
	for _, region := range intent.ActiveRegions {
		selected[region] = struct{}{}
	}

	seats := make([]Seat, 0, len(selected)*SeatsPerRegion)
	for _, region := range regionsInOrder {
		if _, active := selected[region]; !active {
			continue
		}
		regionSeats, err := RegionSeats(region, faultDomains[region], SeatsPerRegion)
		if err != nil {
			return nil, err
		}
		seats = append(seats, regionSeats...)
	}
	return seats, nil
}

// RegionSeatIDs returns one region's fixed seat IDs in placement order: the
// permanent seat (first configured fault domain), then the elastic seat.
func RegionSeatIDs(region oci.Region) ([2]string, error) {
	if !knownRegion(region) {
		return [2]string{}, fmt.Errorf("%w: unsupported region %q", ErrInvalidIntent, region)
	}
	return [2]string{permanentMember(region), elasticMember(region)}, nil
}

func permanentMember(region oci.Region) string {
	if !slices.Contains(regionsInOrder, region) {
		return ""
	}
	return entityid.Derive("placement-seat", string(region), "1")
}

func elasticMember(region oci.Region) string {
	return entityid.Derive("placement-seat", string(region), "2")
}

// knownRegion admits a catalog region only once it has a permanent seat
// mapping: a region added to the catalog without one is rejected instead of
// placing a seat with an empty member ID.
func knownRegion(region oci.Region) bool {
	return slices.Contains(regionsInOrder, region) && permanentMember(region) != ""
}

state_validation.text:
func (state MemberState) EffectiveRuntimeManifest() RuntimeManifest {
	manifest := state.RuntimeManifest
	if state.ManagedRuntimeTarget.OperationID != "" {
		manifest.ArtifactDigest = state.ManagedRuntimeTarget.ArtifactDigest
		manifest.SourceDigest = state.ManagedRuntimeTarget.SourceDigest
	}
	return manifest
}

// PredecessorState is the seat as its current managed target found it: the
// replaced desired generation running the replaced artifact and source. It is
// a comparison value for desired and signed seat pins, never a durable record.
func (state MemberState) PredecessorState() MemberState {
	target := state.ManagedRuntimeTarget
	if target.OperationID == "" {
		return state
	}
	predecessor := state
	predecessor.ManagedRuntimeTarget = ManagedRuntimeTarget{}
	predecessor.DesiredGeneration = target.PreviousDesiredGeneration
	predecessor.RuntimeManifest.ArtifactDigest = target.PreviousArtifactDigest
	if target.PreviousSourceDigest != "" {
		predecessor.RuntimeManifest.SourceDigest = target.PreviousSourceDigest
	}
	return predecessor
}

func (state MemberState) Validate() error {
	validStateFailureDomain := validFailureDomain(state.FailureDomain)
	if state.SchemaVersion != managedUpdateMemberStateSchemaVersion ||
		!entityid.Valid(state.DatabaseID) ||
		!entityid.Valid(state.PartitionID) || !entityid.Valid(state.MemberID) ||
		!knownRegion(state.Region) || !validStateFailureDomain ||
		state.Kind != MemberPermanent && state.Kind != MemberElastic || !knownStage(state.Stage) ||
		!entityid.Valid(state.CreateKey) || state.HostAttempt == 0 || state.IntentGeneration == 0 ||
		stageRequiresHostGeneration(state.Stage) && state.HostGeneration == 0 ||
		!entityid.Valid(state.OperationID) || state.UpdatedAt.IsZero() || state.UpdatedAt.Location() != time.UTC ||
		!state.HostLostAt.IsZero() && state.HostLostAt.Location() != time.UTC ||
		!state.AttachRequestedAt.IsZero() && state.AttachRequestedAt.Location() != time.UTC ||
		state.PreviousInstanceID != "" && (state.HostAttempt < 2 || state.PreviousInstanceID == state.InstanceID) ||
		state.Kind == MemberPermanent && state.MemberID != permanentMember(state.Region) ||
		state.Kind == MemberElastic && state.MemberID != elasticMember(state.Region) {
		return errors.New("invalid TerraBase member state")
	}
	if state.IntentPayloadDigest != "" || state.ManagedHostProfile != (ManagedHostProfile{}) || state.ManagedHostProfileDigest != "" {
		if !validLowerSHA256Digest(state.IntentPayloadDigest) ||
			!validLowerSHA256Digest(state.ManagedHostProfileDigest) ||
			state.ManagedHostProfile.Region != state.Region || state.ManagedHostProfile.Validate() != nil {
			return errors.New("invalid TerraBase member state managed profile pin")
		}
		digest, err := state.ManagedHostProfile.ProfileDigest()
		if err != nil || digest != state.ManagedHostProfileDigest {
			return errors.New("invalid TerraBase member state managed profile digest")
		}
	}
	if !validLowerSHA256Digest(state.IntentPayloadDigest) ||
		!validLowerSHA256Digest(state.ManagedHostProfileDigest) ||
		state.ManagedHostProfile.Region != state.Region || state.ManagedHostProfile.Validate() != nil ||
		state.CanonicalRosterRow.Region != state.Region || state.CanonicalRosterRow.SeatID != state.MemberID ||
		state.CanonicalRosterRow.FailureDomain != state.FailureDomain ||
		!validFailureDomain(state.CanonicalRosterRow.FailureDomain) ||
		!entityid.Valid(state.CanonicalRosterRow.MemberID) ||
		!lowerHex(state.CanonicalRosterRow.Incarnation, 32) || allZeroHex(state.CanonicalRosterRow.Incarnation) ||
		!validLowerSHA256Digest(state.CanonicalRosterRow.TLSLeafSHA256) ||
		!validServerName(state.CanonicalRosterRow.ServerName) ||
		!validLowerSHA256Digest(state.CanonicalRosterDigest) || state.AuthorityReference.Validate() != nil {
		return errors.New("invalid TerraBase member state canonical roster pin")
	}
	if state.Kind == MemberPermanent && state.CanonicalRosterRow.SeatID != permanentMember(state.Region) ||
		state.Kind == MemberElastic && state.CanonicalRosterRow.SeatID != elasticMember(state.Region) {
		return errors.New("invalid TerraBase member state seat pin")
	}
	if state.RuntimeManifest.Region != state.Region || state.RuntimeManifest.SeatID != state.MemberID ||
		!validLowerSHA256Digest(state.RuntimeManifestDigest) {
		return errors.New("invalid TerraBase member runtime manifest pin")
	}
	digest, err := state.RuntimeManifest.Digest()
	if err != nil || digest != state.RuntimeManifestDigest {
		return errors.New("invalid TerraBase member runtime manifest digest")
	}
	if state.SchemaVersion == managedUpdateMemberStateSchemaVersion && state.ManagedRuntimeTarget.OperationID != "" {
		if err := state.ManagedRuntimeTarget.Validate(state); err != nil {
			return err
		}
	}
	if state.Stage == StagePreparedDesired || state.Stage == StageAwaitingHealthy {
		if state.AttachmentDevice == "" || state.AttachmentETag == "" || state.DesiredGeneration == 0 {
			return errors.New("prepared desired lacks observed attachment or generation pin")
		}
	}
	return nil
}

func (target ManagedRuntimeTarget) Validate(state MemberState) error {
	if !entityid.Valid(target.OperationID) || target.AuthoritySequence == 0 ||
		!validLowerSHA256Digest(target.RequestSHA256) ||
		target.PreparedAt.IsZero() || target.PreparedAt.Location() != time.UTC ||
		target.PreparedAt.After(state.UpdatedAt) ||
		target.PlacementGeneration == 0 || target.PlacementGeneration != state.IntentGeneration ||
		!validLowerSHA256Digest(target.PlacementPayloadDigest) ||
		target.PlacementPayloadDigest != state.IntentPayloadDigest ||
		target.CanarySeatID != state.MemberID ||
		target.PreviousDesiredGeneration == 0 || target.PreviousDesiredGeneration == ^uint64(0) ||
		target.DesiredGeneration != target.PreviousDesiredGeneration+1 ||
		target.DesiredGeneration != state.DesiredGeneration ||
		!validLowerSHA256Digest(target.PreviousArtifactDigest) ||
		target.PreviousSourceDigest == "" && target.PreviousArtifactDigest != state.RuntimeManifest.ArtifactDigest ||
		target.PreviousSourceDigest != "" && !validLowerSHA256Digest(target.PreviousSourceDigest) ||
		!validLowerSHA256Digest(target.ArtifactDigest) || target.ArtifactDigest == target.PreviousArtifactDigest ||
		!validLowerSHA256Digest(target.ManifestDigest) || !validLowerSHA256Digest(target.SourceDigest) ||
		target.Phase != ManagedUpdateSeatPrepared && target.Phase != ManagedUpdateSeatCanaryServing &&
			target.Phase != ManagedUpdateSeatHeld {
		return errors.New("invalid managed canary runtime target")
	}
	if target.Phase == ManagedUpdateSeatPrepared {
		if target.Outcome != "" {
			return errors.New("prepared managed runtime target cannot carry an outcome")
		}
	} else if target.Outcome == "" || len(target.Outcome) > 256 ||
		strings.ContainsAny(target.Outcome, "\r\n\x00") {
		return errors.New("terminal managed runtime target requires a bounded outcome")
	}
	return nil
}

func validLowerSHA256Digest(value string) bool {
	if len(value) != sha256.Size*2 {
		return false
	}
	digest, err := hex.DecodeString(value)
	return err == nil && hex.EncodeToString(digest) == value
}

func validFilesystemUUID(value string) bool {
	if len(value) != 36 {
		return false
	}
	for index, character := range value {
		if index == 8 || index == 13 || index == 18 || index == 23 {
			if character != '-' {
				return false
			}
		} else if character < '0' || character > '9' && (character < 'a' || character > 'f') {
			return false
		}
	}
	return true
}

func validPrivateIPv4Endpoint(value string) bool {
	endpoint, err := netip.ParseAddrPort(value)
	return err == nil && endpoint.String() == value && endpoint.Port() != 0 &&
		endpoint.Addr().Is4() && endpoint.Addr().IsPrivate()
}

func knownStage(stage MemberStage) bool {
	switch stage {
	case StagePreparedHost, StageAwaitingHost, StagePreparedVolume, StagePreparedAttach, StageAwaitingAttach,
		StagePreparedDesired, StageAwaitingRuntimeContract, StageAwaitingHealthy, StageServing,
		StageRemoveCandidate, StageCordoned, StageDraining, StageDrained, StageStorageHandled, StageTerminated, StageRemoved:
		return true
	default:
		return false
	}
}

func stageRequiresHostGeneration(stage MemberStage) bool {
	switch stage {
	case StagePreparedHost, StageAwaitingHost:
		return false
	default:
		return true
	}
}

retirement_predicates.text:
func CanRetire(intent Intent, candidate MemberObservation, survivors []MemberObservation, evidence RetirementEvidence) (bool, string) {
	if allowed, reason := retirementTopologySafe(intent, candidate, survivors); !allowed {
		return false, reason
	}
	if allowed, reason := retirementEvidenceSafe(evidence, candidate, true); !allowed {
		return false, reason
	}
	return true, "safe-to-retire"
}

// retirementEvidenceSafe holds the identity, replication, quorum, writer-stop
// and retained-volume checks shared by retirement and lost-member
// replacement. Drain is retirement-only: a lost member cannot be drained.
func retirementEvidenceSafe(evidence RetirementEvidence, candidate MemberObservation, requireDrain bool) (bool, string) {
	if !evidenceMatchesCandidate(evidence, candidate) {
		return false, "retirement-evidence-identity-mismatch"
	}
	if !evidence.ReplicationHealthy {
		return false, "replication-health-unverified"
	}
	if !evidence.QuorumSafe {
		return false, "quorum-safety-unverified"
	}
	if requireDrain && !evidence.HostDrained {
		return false, "host-drain-unverified"
	}
	if !evidence.WriterStopped || len(evidence.WriterStopProof) == 0 {
		return false, "writer-stop-unverified"
	}
	if !evidence.VolumeRetained {
		return false, "retained-volume-decision-unverified"
	}
	return true, "evidence-safe"
}

// CanBeginRetirement is the pre-drain gate. It permits cordon/drain only after
// the intent no longer needs the candidate and every selected region retains
// two serving members on distinct failure domains. Provider removal still
// requires CanRetire with fresh drain and writer-stop evidence.
func CanBeginRetirement(intent Intent, candidate MemberObservation, survivors []MemberObservation, evidence RetirementEvidence) (bool, string) {
	if candidate.Stage != StageServing || !candidate.Healthy || !candidate.CurrentSession {
		return false, "candidate-health-or-session-unverified"
	}
	if allowed, reason := retirementTopologySafe(intent, candidate, survivors); !allowed {
		return false, reason
	}
	if !evidenceMatchesCandidate(evidence, candidate) {
		return false, "retirement-evidence-identity-mismatch"
	}
	if !evidence.ReplicationHealthy {
		return false, "replication-health-unverified"
	}
	if !evidence.QuorumSafe {
		return false, "quorum-safety-unverified"
	}
	return true, "safe-to-begin-retirement"
}

func retirementTopologySafe(intent Intent, candidate MemberObservation, survivors []MemberObservation) (bool, string) {
	if err := intent.Validate(); err != nil {
		return false, "invalid-intent"
	}
	if candidate.DatabaseID != intent.DatabaseID || candidate.PartitionID != intent.PartitionID ||
		candidate.MemberID == "" || candidate.Region == "" || !knownRegion(candidate.Region) ||
		candidate.InstanceID == "" || candidate.VolumeID == "" {
		return false, "candidate-identity-missing"
	}
	if !removableStage(candidate.Stage) {
		return false, "candidate-stage-invalid"
	}
	if desiredMember(intent, candidate.Region, candidate.MemberID) {
		return false, "candidate-still-desired"
	}
	for _, member := range survivors {
		if member.DatabaseID != intent.DatabaseID || member.PartitionID != intent.PartitionID {
			return false, "survivor-identity-mismatch"
		}
	}
	for _, region := range intent.ActiveRegions {
		memberCount := 0
		failureDomains := make(map[string]struct{}, 2)
		for _, member := range survivors {
			if member.Region != region || member.MemberID == candidate.MemberID || member.Stage != StageServing ||
				!member.Healthy || !member.CurrentSession {
				continue
			}
			if member.FailureDomain == "" {
				return false, "survivor-failure-domain-unverified"
			}
			if _, exists := failureDomains[member.FailureDomain]; exists {
				return false, "survivor-anti-affinity-violated"
			}
			failureDomains[member.FailureDomain] = struct{}{}
			memberCount++
		}
		if memberCount < 2 {
			return false, "replica-floor-or-health-not-met"
		}
	}
	return true, "topology-safe"
}

func evidenceMatchesCandidate(evidence RetirementEvidence, candidate MemberObservation) bool {
	return evidence.DatabaseID == candidate.DatabaseID && evidence.PartitionID == candidate.PartitionID &&
		evidence.MemberID == candidate.MemberID && evidence.InstanceID == candidate.InstanceID &&
		evidence.VolumeID == candidate.VolumeID
}

func desiredMember(intent Intent, region oci.Region, memberID string) bool {
	if !slices.Contains(intent.ActiveRegions, region) {
		return false
	}
	return memberID == permanentMember(region) || memberID == elasticMember(region)
}

func removableStage(stage MemberStage) bool {
	switch stage {
	case StageServing, StageRemoveCandidate, StageCordoned, StageDraining, StageDrained, StageStorageHandled:
		return true
	default:
		return false
	}
}

metrics_summary.text:
// maxSummarizedPartitions bounds one Summarize call. Each partition costs a
// member list and a terminal-intent read; the summary is cached by its caller.
const maxSummarizedPartitions = 256

var (
	reconcileSeries = func(result string) *metrics.Counter {
		return Metrics.NewCounter(observability.Series(observability.MetricPrefix+"reconcile_total",
			"loop", "placement", "result", result))
	}
	reconcileOK      = reconcileSeries("ok")
	reconcileError   = reconcileSeries("error")
	reconcileStandby = reconcileSeries("standby")
	reconcileSeconds = Metrics.NewPrometheusHistogram(observability.Series(
		observability.MetricPrefix+"reconcile_duration_seconds", "loop", "placement"))
	lastReconcileSuccess atomic.Int64
	_                    = Metrics.NewGauge(observability.Series(
		observability.MetricPrefix+"reconcile_last_success_timestamp_seconds", "loop", "placement"),
		func() float64 {
			if at := lastReconcileSuccess.Load(); at > 0 {
				return float64(at) / 1e9
			}
			return math.NaN()
		})
)

// recordReconcile counts one Run tick. A standby tick is one where this
// member did not hold a writable lease when the tick started.
func recordReconcile(started time.Time, standby bool, err error) {
	switch {
	case standby:
		reconcileStandby.Inc()
		return
	case err != nil:
		reconcileError.Inc()
	default:
		reconcileOK.Inc()
		lastReconcileSuccess.Store(time.Now().UnixNano())
	}
	reconcileSeconds.UpdateDuration(started)
}

// Summarize reads durable placement state into a dashboard view: every
// admitted partition's roster progress, stage counts and the progress of its
// most recently prepared managed runtime update. It is read-only.
func Summarize(ctx context.Context, store Store) (observability.PlacementView, error) {
	if store == nil {
		return observability.PlacementView{}, errors.New("placement summary requires a store")
	}
	intents, err := store.ListIntents(ctx)
	if err != nil {
		return observability.PlacementView{}, err
	}
	view := observability.PlacementView{StageCounts: map[string]int{}}
	for index, intent := range intents {
		if index >= maxSummarizedPartitions {
			view.Truncated = true
			break
		}
		members, err := store.ListMembers(ctx, intent.DatabaseID, intent.PartitionID)
		if err != nil {
			return observability.PlacementView{}, err
		}
		database := summarizePartition(intent, members)
		if _, err := store.ReadTerminalIntent(ctx, intent.DatabaseID, intent.PartitionID); err == nil {
			database.Terminal = true
		} else if !errors.Is(err, authority.ErrNotFound) {
			return observability.PlacementView{}, err
		}
		for stage, count := range database.Stages {
			view.StageCounts[stage] += count
		}
		view.Databases = append(view.Databases, database)
	}
	return view, nil
}

func summarizePartition(intent Intent, members []VersionedMemberState) observability.DatabaseView {
	database := observability.DatabaseView{DatabaseID: intent.DatabaseID, PartitionID: intent.PartitionID,
		Generation: intent.Generation, DesiredSeats: len(intent.CanonicalRoster.Rows), Stages: map[string]int{},
		Readiness: "unknown", ReadinessReason: "current native root task and member readiness source is unavailable"}
	var latest *ManagedRuntimeTarget
	for index := range members {
		state := members[index].State
		stage := string(state.Stage)
		database.Stages[stage]++
		database.Members = append(database.Members, observability.MemberView{SeatID: state.MemberID,
			Stage: stage, HostNode: state.HostNode, FailureDomain: state.FailureDomain,
			UpdatePhase: string(state.ManagedRuntimeTarget.Phase), UpdatedAt: state.UpdatedAt})
		target := &members[index].State.ManagedRuntimeTarget
		if target.OperationID != "" && (latest == nil || target.PreparedAt.After(latest.PreparedAt)) {
			latest = target
		}
	}
	if latest == nil {
		return database
	}
	// A managed update operation targets its own seats (one canary per
	// operation), so its progress is over the seats it targets, not every
	// placement seat: otherwise a finished update reads as stalled at 1/2.
	rollout := &observability.RolloutView{OperationID: latest.OperationID, ArtifactDigest: latest.ArtifactDigest,
		Phases: map[string]int{}}
	for _, member := range members {
		target := member.State.ManagedRuntimeTarget
		if target.OperationID != latest.OperationID {
			continue
		}
		rollout.Seats++
		rollout.Phases[string(target.Phase)]++
		if target.Phase == ManagedUpdateSeatCanaryServing && member.State.Stage == StageServing {
			rollout.Completed++
		}
	}
	database.Rollout = rollout
	return database
}

seat_layout.text:
func ElasticSeatID(region oci.Region, ordinal int) string {
	return entityid.Derive("placement-seat", string(region), strconv.Itoa(ordinal+1))
}

// seatMemberName is a seat's static member name in placement order: the
// permanent seat is member 1 and elastic seat k is member k+1, e.g.
// gru-1-db-2 for elastic-gru. Host attempts and generations never change it.
func seatMemberName(region oci.Region, memberID string) (string, error) {
	if !knownRegion(region) {
		return "", fmt.Errorf("%w: unsupported region", ErrInvalidIntent)
	}
	for n := 1; n <= 3; n++ {
		id := permanentMember(region)
		if n > 1 {
			id = ElasticSeatID(region, n-1)
		}
		if memberID == id {
			return naming.RegionCell(string(region)).Server(naming.Member, n)
		}
	}
	return "", fmt.Errorf("%w: seat %q has no member name", ErrInvalidIntent, memberID)
}

// RegionSeats returns one region's seats in placement order: the permanent
// seat on the first configured fault domain, then elastic seats 1..count-1.
// Members of one region never share a fault domain, so count is bounded by
// the configured distinct fault domains as well as below by the quorum floor.
func RegionSeats(region oci.Region, faultDomains []string, count int) ([]Seat, error) {
	if !knownRegion(region) {
		return nil, fmt.Errorf("%w: unsupported region %q", ErrInvalidIntent, region)
	}
	if count < MinSeatsPerRegion {
		return nil, fmt.Errorf("%w: region %s needs at least %d seats", ErrInvalidIntent, region, MinSeatsPerRegion)
	}
	if len(faultDomains) < count {
		return nil, fmt.Errorf("%w: region %s needs %d distinct configured fault domains", ErrInvalidIntent, region, count)
	}
	seen := make(map[string]struct{}, count)
	for _, domain := range faultDomains[:count] {
		if !validFailureDomain(domain) {
			return nil, fmt.Errorf("%w: region %s has an invalid fault domain", ErrInvalidIntent, region)
		}
		if _, exists := seen[domain]; exists {
			return nil, fmt.Errorf("%w: region %s needs %d distinct configured fault domains", ErrInvalidIntent, region, count)
		}
		seen[domain] = struct{}{}
	}
	permanentID := permanentMember(region)
	if permanentID == "" {
		return nil, fmt.Errorf("%w: region %s has no permanent member mapping", ErrInvalidIntent, region)
	}
	seats := make([]Seat, 0, count)
	seats = append(seats, Seat{MemberID: permanentID, Region: region, FailureDomain: faultDomains[0], Kind: MemberPermanent})
	for ordinal := 1; ordinal < count; ordinal++ {
		seats = append(seats, Seat{MemberID: ElasticSeatID(region, ordinal), Region: region,
			FailureDomain: faultDomains[ordinal], Kind: MemberElastic})
	}
	return seats, nil
}

replacement.text:
func CanReplaceLostMember(intent Intent, lost MemberObservation, survivors []MemberObservation,
	evidence RetirementEvidence,
) (bool, string) {
	if err := intent.Validate(); err != nil {
		return false, "invalid-intent"
	}
	if lost.DatabaseID != intent.DatabaseID || lost.PartitionID != intent.PartitionID || lost.MemberID == "" ||
		!knownRegion(lost.Region) || lost.InstanceID == "" || lost.VolumeID == "" {
		return false, "candidate-identity-missing"
	}
	if lost.Stage != StageAwaitingRuntimeContract || lost.Healthy || lost.CurrentSession {
		return false, "candidate-not-lost"
	}
	if !desiredMember(intent, lost.Region, lost.MemberID) {
		return false, "candidate-not-desired"
	}
	survivor := false
	for _, member := range survivors {
		if member.DatabaseID != intent.DatabaseID || member.PartitionID != intent.PartitionID {
			return false, "survivor-identity-mismatch"
		}
		if member.MemberID == lost.MemberID || member.Region != lost.Region || member.Stage != StageServing ||
			!member.Healthy || !member.CurrentSession {
			continue
		}
		if member.FailureDomain == "" || member.FailureDomain == lost.FailureDomain {
			return false, "survivor-anti-affinity-violated"
		}
		survivor = true
	}
	if !survivor {
		return false, "no-serving-survivor"
	}
	if allowed, reason := retirementEvidenceSafe(evidence, lost, false); !allowed {
		return false, reason
	}
	return true, "safe-to-replace"
}

// replacementMemberState is the next host attempt for the same seat. It keeps
// the retained volume, roster, manifest and private IP, and clears every
// identity of the lost host so it can never be adopted again.
func replacementMemberState(intent Intent, seat Seat, state MemberState) (MemberState, error) {
	if state.HostAttempt == 0 || state.HostAttempt == ^uint64(0) || state.VolumeID == "" {
		return MemberState{}, fmt.Errorf("%w: lost member has no retained volume or attempt", ErrStoreCorrupt)
	}
	next := state
	next.HostAttempt = state.HostAttempt + 1
	next.CreateKey = hostCreateKey(intent, seat, next.HostAttempt)
	next.Stage = StagePreparedHost
	next.PreviousInstanceID = state.InstanceID
	next.HostNode, next.InstanceID, next.InstanceETag = "", "", ""
	next.AttachmentID, next.AttachmentDevice, next.AttachmentETag = "", "", ""
	next.HostGeneration, next.DesiredGeneration = 0, 0
	next.HostLostAt, next.AttachRequestedAt = time.Time{}, time.Time{}
	next.OperationID = memberOperationID(intent, seat.MemberID, next.HostAttempt, "replace")
	return next, nil
}

// replaceLostMember starts the next host attempt for a seat held without its
// OCI host once the grace passed and the evidence gate allows it. Without a
// configured evidence source the member stays held, as before.
func (controller *Controller) replaceLostMember(ctx context.Context, epoch uint64, intent Intent, seat Seat,
	versioned VersionedMemberState, seats []Seat, members map[string]VersionedMemberState,
	instances map[string]oci.Instance, statuses map[string]host.HostStatus,
) (bool, error) {
	state := versioned.State
	if controller.config.LostMemberEvidence == nil || state.Stage != StageAwaitingRuntimeContract ||
		state.ManagedRuntimeTarget.OperationID != "" {
		return false, nil
	}
	if state.InstanceID == "" {
		return false, nil
	}
	instance, observed := instances[state.InstanceID]
	// A host that is still observed may return and is never replaced; a
	// host OCI positively reports TERMINATED cannot return, even while the
	// historical instance still appears in the inventory.
	if observed && instance.State != instanceLifecycleTerminated {
		if state.HostLostAt.IsZero() {
			return false, nil
		}
		// The host came back: a later loss starts a fresh grace.
		next := state
		next.HostLostAt = time.Time{}
		if err := controller.guard(ctx, epoch); err != nil {
			return false, err
		}
		_, err := controller.persist(ctx, epoch, versioned.Revision, next)
		return true, err
	}
	now := controller.currentTime().UTC()
	if state.HostLostAt.IsZero() {
		// Record the first observation of the loss durably; the grace runs
		// from here, not from the member's last unrelated write.
		next := state
		next.HostLostAt = now
		if err := controller.guard(ctx, epoch); err != nil {
			return false, err
		}
		_, err := controller.persist(ctx, epoch, versioned.Revision, next)
		return true, err
	}
	grace := controller.config.LostMemberGrace
	if grace == 0 {
		grace = DefaultLostMemberGrace
	}
	if now.Sub(state.HostLostAt) < grace {
		return false, nil
	}
	evidence, complete, err := controller.config.LostMemberEvidence(ctx, state)
	if err != nil {
		return false, fmt.Errorf("read lost member %s evidence: %w", seat.MemberID, err)
	}
	if !complete {
		controller.hold(fmt.Sprintf("member %s lost its host; replacement awaits writer-stop, retained-volume and survivor replication evidence", seat.MemberID))
		return false, nil
	}
	lost := MemberObservation{DatabaseID: state.DatabaseID, PartitionID: state.PartitionID, MemberID: state.MemberID,
		Region: state.Region, FailureDomain: state.FailureDomain, InstanceID: state.InstanceID,
		VolumeID: state.VolumeID, Stage: state.Stage}
	survivors := make([]MemberObservation, 0, len(seats))
	for _, other := range seats {
		if other.MemberID == seat.MemberID {
			continue
		}
		peer, exists := members[other.MemberID]
		if !exists {
			continue
		}
		survivors = append(survivors, controller.observeMember(intent, peer.State, instances, statuses))
	}
	if allowed, reason := CanReplaceLostMember(intent, lost, survivors, evidence); !allowed {
		controller.hold(fmt.Sprintf("member %s lost its host; replacement is held: %s", seat.MemberID, reason))
		return false, nil
	}
	next, err := replacementMemberState(intent, seat, state)
	if err != nil {
		return false, err
	}
	if err := controller.guard(ctx, epoch); err != nil {
		return false, err
	}
	_, err = controller.persist(ctx, epoch, versioned.Revision, next)
	return true, err
}

// observeMember reports a member's current serving health from the same
// host, instance and serving-report evidence the Serving stage uses.
func (controller *Controller) observeMember(intent Intent, state MemberState, instances map[string]oci.Instance,
	statuses map[string]host.HostStatus,
) MemberObservation {
	observation := MemberObservation{DatabaseID: state.DatabaseID, PartitionID: state.PartitionID,
		MemberID: state.MemberID, Region: state.Region, FailureDomain: state.FailureDomain,
		InstanceID: state.InstanceID, VolumeID: state.VolumeID, Stage: state.Stage}
	instance, exists := instances[state.InstanceID]
	if !exists || state.Stage != StageServing {
		return observation
	}
	status, admitted := controller.admittedHost(intent, state, instance, statuses)
	if admitted && status.Registration.Generation == state.HostGeneration &&
		controller.hasServingReport(intent, state, instance, status) {
		observation.Healthy, observation.CurrentSession = true, true
	}
	return observation
}

reattach.text:
func (controller *Controller) reattachRetainedVolume(ctx context.Context, epoch uint64, intent Intent, seat Seat,
	versioned VersionedMemberState,
) (bool, error) {
	state := versioned.State
	boundary, supported := failover.NewOCIBoundary(controller.fleet)
	if !supported {
		controller.hold(fmt.Sprintf("member %s replacement needs reattach on host loss, which the OCI fleet does not support", seat.MemberID))
		return false, nil
	}
	// Hold one workload effect bound to this tick's epoch for the whole step.
	// Every nested OCI effect joins it through the shared effect context, so
	// an authority loss and reacquire mid-step fences the nested effect
	// instead of letting it run under the new epoch with this tick's inputs.
	ctx = authority.WithActiveWorkloadEffectContext(ctx)
	release, err := controller.beginWorkloadEffect(ctx, epoch, intent)
	if err != nil {
		return false, err
	}
	defer release()
	if state.AttachRequestedAt.IsZero() {
		// The attach deadline runs from the first reattach step, durably.
		state.AttachRequestedAt = controller.currentTime().UTC()
		if err := controller.guard(ctx, epoch); err != nil {
			return false, err
		}
		revision, err := controller.persist(ctx, epoch, versioned.Revision, state)
		if err != nil {
			return false, err
		}
		versioned.Revision = revision
	}
	reattacher := failover.Reattacher{
		Fencer:    controller.fencer,
		Instances: boundary, Volumes: boundary, Permits: boundary, Now: controller.currentTime,
		// The member state was read under this tick's epoch; a step under a
		// later epoch must not act on it.
		ExpectedEpoch: epoch,
	}
	request := failover.Request{
		DatabaseID: intent.DatabaseID, PartitionID: intent.PartitionID, VolumeID: state.VolumeID,
		OldInstanceID: state.PreviousInstanceID, ReplacementInstanceID: state.InstanceID,
		AttachKey: memberOperationID(intent, seat.MemberID, state.HostAttempt, "attach-volume"),
	}
	if err := controller.guard(ctx, epoch); err != nil {
		return false, err
	}
	step, err := reattacher.Step(ctx, request)
	switch step.Kind {
	case failover.StepProveFence:
		if errors.Is(err, failover.ErrFenceUnobserved) {
			// A failed lookup is not a wait for TERMINATED: report it.
			controller.holdStalledAttachRequest(seat.MemberID, state)
			return false, fmt.Errorf("reattach retained member volume %s/%s: prove lost instance %s fenced: %w",
				intent.DatabaseID, seat.MemberID, state.PreviousInstanceID, err)
		}
		controller.hold(fmt.Sprintf("member %s replacement waits for OCI to report lost instance %s TERMINATED before its volume moves",
			seat.MemberID, state.PreviousInstanceID))
		controller.holdStalledAttachRequest(seat.MemberID, state)
		return false, nil
	case failover.StepHold:
		reason := step.Reason
		if err != nil && !errors.Is(err, storage.ErrVolumeHeld) {
			return false, err
		}
		controller.hold(fmt.Sprintf("member %s retained volume reattach is held for an operator: %s", seat.MemberID, reason))
		return false, nil
	case failover.StepWaitDetached:
		controller.hold(fmt.Sprintf("member %s retained volume waits for the lost instance's attachment %s to reach DETACHED",
			seat.MemberID, step.Attachment.ID))
		controller.holdStalledAttachRequest(seat.MemberID, state)
		return false, nil
	case failover.StepWaitAttached:
		controller.holdStuckAttachment(seat.MemberID, step.Attachment.ID, state)
		return false, nil
	case failover.StepDetach, failover.StepGrantMount:
		if err != nil {
			return false, fmt.Errorf("reattach retained member volume %s/%s (%s): %w", intent.DatabaseID, seat.MemberID, step.Kind, err)
		}
		return true, nil
	case failover.StepAttach:
		if err != nil {
			controller.holdStalledAttachRequest(seat.MemberID, state)
			return false, fmt.Errorf("reattach retained member volume %s/%s: %w", intent.DatabaseID, seat.MemberID, err)
		}
		return true, nil
	case failover.StepDone:
		if err != nil {
			return false, err
		}
		if step.Attachment.ID == "" || step.Attachment.InstanceID != state.InstanceID || step.Attachment.VolumeID != state.VolumeID {
			return false, errors.New("reattach completed with a mismatched replacement attachment")
		}
		if err := controller.guard(ctx, epoch); err != nil {
			return false, err
		}
		state.AttachmentID = step.Attachment.ID
		state.AttachRequestedAt = time.Time{}
		state.Stage = StageAwaitingRuntimeContract
		state.OperationID = memberOperationID(intent, seat.MemberID, state.HostAttempt, "runtime-hold")
		_, err = controller.persist(ctx, epoch, versioned.Revision, state)
		return true, err
	default:
		if err != nil {
			return false, fmt.Errorf("reattach retained member volume %s/%s: %w", intent.DatabaseID, seat.MemberID, err)
		}
		return false, fmt.Errorf("reattach retained member volume %s/%s returned step %q", intent.DatabaseID, seat.MemberID, step.Kind)
	}
}

failover_adapter.text:
// OCIFleet is the slice of the OCI fleet a reattach drives: the journaled
// reattach boundary plus the regular retained-volume attach.
type OCIFleet interface {
	oci.VolumeReattacher
	AttachRetainedVolume(context.Context, oci.VolumeAttachRequest) (oci.Attachment, error)
}

// OCIBoundary adapts the OCI fleet to the Reattacher's instance, volume and
// permit boundaries. Every effect stays journaled and epoch-fenced inside
// internal/oci; this adapter only translates types.
type OCIBoundary struct {
	Fleet OCIFleet
}

// NewOCIBoundary returns the adapter when fleet supports reattach.
func NewOCIBoundary(fleet any) (OCIBoundary, bool) {
	supported, ok := fleet.(OCIFleet)
	if !ok || supported == nil {
		return OCIBoundary{}, false
	}
	return OCIBoundary{Fleet: supported}, true
}

func (boundary OCIBoundary) InstanceLifecycleState(ctx context.Context, instanceID string) (string, error) {
	if boundary.Fleet == nil {
		return "", errors.New("reattach OCI boundary has no fleet")
	}
	return boundary.Fleet.FencedInstanceState(ctx, instanceID)
}

func (boundary OCIBoundary) VolumeAttachments(ctx context.Context, volumeID string) ([]Attachment, error) {
	if boundary.Fleet == nil {
		return nil, errors.New("reattach OCI boundary has no fleet")
	}
	listed, err := boundary.Fleet.RetainedVolumeAttachments(ctx, volumeID)
	if err != nil {
		return nil, err
	}
	attachments := make([]Attachment, 0, len(listed))
	for _, attachment := range listed {
		attachments = append(attachments, fromOCI(attachment))
	}
	return attachments, nil
}

func (boundary OCIBoundary) DetachFenced(ctx context.Context, request Request, attachment Attachment, proof FenceProof) error {
	if boundary.Fleet == nil {
		return errors.New("reattach OCI boundary has no fleet")
	}
	if proof.InstanceID != request.OldInstanceID || proof.State != "TERMINATED" ||
		attachment.InstanceID != request.OldInstanceID || attachment.VolumeID != request.VolumeID {
		return ErrFenceProofMismatch
	}
	return boundary.Fleet.DetachFencedAttachment(ctx, oci.FencedDetachRequest{
		DatabaseID: request.DatabaseID, PartitionID: request.PartitionID,
		AttachmentID: attachment.ID, ExpectedETag: attachment.ETag, InstanceID: attachment.InstanceID,
	})
}

func (boundary OCIBoundary) AttachReplacement(ctx context.Context, request Request, proof FenceProof) (Attachment, error) {
	if boundary.Fleet == nil {
		return Attachment{}, errors.New("reattach OCI boundary has no fleet")
	}
	if proof.InstanceID != request.OldInstanceID || proof.State != "TERMINATED" {
		return Attachment{}, ErrFenceProofMismatch
	}
	attached, err := boundary.Fleet.AttachRetainedVolume(ctx, oci.VolumeAttachRequest{
		DatabaseID: request.DatabaseID, PartitionID: request.PartitionID,
		VolumeID: request.VolumeID, InstanceID: request.ReplacementInstanceID,
		IdempotencyKey: request.AttachKey, AllowDetachedHistory: true,
	})
	if err != nil {
		return Attachment{}, err
	}
	return fromOCI(attached), nil
}

func (boundary OCIBoundary) GrantMountExisting(ctx context.Context, request Request, attachment Attachment) error {
	if boundary.Fleet == nil {
		return errors.New("reattach OCI boundary has no fleet")
	}
	return boundary.Fleet.GrantVolumeMountExisting(ctx, mountPermit(request, attachment))
}

func (boundary OCIBoundary) HasMountExisting(ctx context.Context, request Request, attachment Attachment) (bool, error) {
	if boundary.Fleet == nil {
		return false, errors.New("reattach OCI boundary has no fleet")
	}
	return boundary.Fleet.HasVolumeMountExisting(ctx, mountPermit(request, attachment))
}

// ErrFenceProofMismatch reports a fence proof that does not name the
// request's old instance as TERMINATED.
var ErrFenceProofMismatch = errors.New("reattach fence proof does not match the lost instance")

func mountPermit(request Request, attachment Attachment) oci.VolumeMountPermit {
	return oci.VolumeMountPermit{
		DatabaseID: request.DatabaseID, PartitionID: request.PartitionID, VolumeID: request.VolumeID,
		AttachmentID: attachment.ID, ReplacementInstanceID: request.ReplacementInstanceID,
		FencedInstanceID: request.OldInstanceID,
	}
}

func fromOCI(attachment oci.Attachment) Attachment {
	return Attachment{ID: attachment.ID, VolumeID: attachment.VolumeID, InstanceID: attachment.InstanceID,
		State: attachment.State, ETag: attachment.ETag}
}

failover_machine.text:
type Request struct {
	DatabaseID, PartitionID string
	VolumeID                string
	OldInstanceID           string
	ReplacementInstanceID   string
	// AttachKey is the stable idempotency key of the replacement attach.
	AttachKey string
}

func (request Request) validate() error {
	if request.DatabaseID == "" || request.PartitionID == "" || request.VolumeID == "" ||
		request.OldInstanceID == "" || request.ReplacementInstanceID == "" || request.AttachKey == "" {
		return errors.New("reattach request is incomplete")
	}
	if request.OldInstanceID == request.ReplacementInstanceID {
		return errors.New("reattach replacement must be a different instance")
	}
	return nil
}

// StepKind is the next action of a reattach.
type StepKind string

const (
	StepProveFence   StepKind = "prove-fence"
	StepDetach       StepKind = "detach"
	StepWaitDetached StepKind = "wait-detached"
	StepAttach       StepKind = "attach"
	StepWaitAttached StepKind = "wait-attached"
	StepGrantMount   StepKind = "grant-mount-existing"
	StepDone         StepKind = "done"
	StepHold         StepKind = "hold"
)

// Step is the decided next action.
type Step struct {
	Kind       StepKind
	Attachment Attachment
	Reason     string
}

// Decide chooses the next step. fenced must come from ProveFenced for
// request.OldInstanceID. mounted reports that the replacement already holds a
// current mount-existing permit.
func Decide(request Request, fenced bool, attachments []Attachment, mounted bool) Step {
	if !fenced {
		return Step{Kind: StepProveFence, Reason: "old writer is not proven fenced"}
	}
	var replacement *Attachment
	for index := range attachments {
		attachment := attachments[index]
		if attachment.VolumeID != request.VolumeID {
			return Step{Kind: StepHold, Attachment: attachment, Reason: "attachment listing returned another volume"}
		}
		switch attachment.InstanceID {
		case request.OldInstanceID:
			switch attachment.State {
			case "DETACHED":
			case "DETACHING":
				return Step{Kind: StepWaitDetached, Attachment: attachment}
			case "ATTACHED", "ATTACHING":
				return Step{Kind: StepDetach, Attachment: attachment}
			default:
				return Step{Kind: StepHold, Attachment: attachment, Reason: "old attachment is in unknown state " + attachment.State}
			}
		case request.ReplacementInstanceID:
			if attachment.State == "DETACHED" {
				continue
			}
			if replacement != nil {
				return Step{Kind: StepHold, Attachment: attachment, Reason: "replacement has more than one live attachment"}
			}
			replacement = &attachments[index]
		default:
			if attachment.State != "DETACHED" {
				// A third writer was never proven fenced.
				return Step{Kind: StepHold, Attachment: attachment, Reason: "volume is attached to an unrelated instance"}
			}
		}
	}
	if replacement == nil {
		return Step{Kind: StepAttach}
	}
	switch replacement.State {
	case "ATTACHING":
		return Step{Kind: StepWaitAttached, Attachment: *replacement}
	case "ATTACHED":
		if mounted {
			return Step{Kind: StepDone, Attachment: *replacement}
		}
		return Step{Kind: StepGrantMount, Attachment: *replacement}
	default:
		return Step{Kind: StepHold, Attachment: *replacement, Reason: "replacement attachment is " + replacement.State}
	}
}

// InstanceObserver reads an instance's OCI lifecycle state.
type InstanceObserver interface {
	InstanceLifecycleState(ctx context.Context, instanceID string) (string, error)
}

// ProveFenced returns proof only when OCI reports the instance TERMINATED.
// TERMINATING, STOPPED or an unreachable host are not proof: a stopped
// instance can be started again with the volume still attached.
func ProveFenced(ctx context.Context, observer InstanceObserver, instanceID string, now time.Time) (FenceProof, error) {
	state, err := observer.InstanceLifecycleState(ctx, instanceID)
	if err != nil {
		return FenceProof{}, errors.Join(storage.ErrWriterNotFenced, ErrFenceUnobserved, err)
	}
	if state != "TERMINATED" {
		return FenceProof{}, fmt.Errorf("%w: instance %s is %s", storage.ErrWriterNotFenced, instanceID, state)
	}
	return FenceProof{InstanceID: instanceID, State: state, ObservedAt: now.UTC()}, nil
}

// ErrFenceUnobserved marks a missing fence proof caused by a failed lifecycle
// lookup (authorization, network, cancellation, a purged instance) rather
// than an observed non-TERMINATED state. Callers report it as an error
// instead of a normal wait.
var ErrFenceUnobserved = errors.New("lost instance lifecycle state could not be observed")

// VolumeAttacher is the journaled OCI attachment boundary used by reattach.
type VolumeAttacher interface {
	VolumeAttachments(ctx context.Context, volumeID string) ([]Attachment, error)
	// DetachFenced detaches an attachment of a proven-terminated instance.
	DetachFenced(ctx context.Context, request Request, attachment Attachment, proof FenceProof) error
	AttachReplacement(ctx context.Context, request Request, proof FenceProof) (Attachment, error)
}

// MountPermitter grants a one-time mount-existing permit; it must never
// grant format authority for a reattached volume.
type MountPermitter interface {
	GrantMountExisting(ctx context.Context, request Request, attachment Attachment) error
	HasMountExisting(ctx context.Context, request Request, attachment Attachment) (bool, error)
}

// Reattacher executes one reattach step per call on the authority leader.
type Reattacher struct {
	Fencer    authority.Fencer
	Instances InstanceObserver
	Volumes   VolumeAttacher
	Permits   MountPermitter
	Now       func() time.Time
	// ExpectedEpoch, when non-zero, binds the step to the authority epoch
	// under which the caller read its inputs: a step under any other epoch
	// is fenced before anything is read or changed.
	ExpectedEpoch uint64
}

// Step decides and executes the next step and returns it. StepHold and
// StepProveFence return an error wrapping the reason.
func (reattacher Reattacher) Step(ctx context.Context, request Request) (Step, error) {
	if err := request.validate(); err != nil {
		return Step{}, err
	}
	if reattacher.Fencer == nil || reattacher.Instances == nil || reattacher.Volumes == nil || reattacher.Permits == nil {
		return Step{}, errors.New("reattacher requires authority, instance, volume and permit boundaries")
	}
	snapshot := reattacher.Fencer.Current()
	if !snapshot.CanMutate() {
		return Step{}, authority.ErrNotLeader
	}
	epoch := snapshot.Epoch
	if reattacher.ExpectedEpoch != 0 && epoch != reattacher.ExpectedEpoch {
		return Step{}, authority.ErrFenced
	}
	now := time.Now
	if reattacher.Now != nil {
		now = reattacher.Now
	}
	proof, proofErr := ProveFenced(ctx, reattacher.Instances, request.OldInstanceID, now())
	fenced := proofErr == nil
	if !fenced {
		// Nothing past the fence proof is decided while it is missing, so
		// the attachment listing is not read for this step.
		return Decide(request, false, nil, false), proofErr
	}
	attachments, err := reattacher.Volumes.VolumeAttachments(ctx, request.VolumeID)
	if err != nil {
		return Step{}, err
	}
	mounted := false
	step := Decide(request, fenced, attachments, false)
	if step.Kind == StepGrantMount {
		if mounted, err = reattacher.Permits.HasMountExisting(ctx, request, step.Attachment); err != nil {
			return Step{}, err
		}
		step = Decide(request, fenced, attachments, mounted)
	}
	switch step.Kind {
	case StepProveFence:
		return step, proofErr
	case StepHold:
		return step, fmt.Errorf("%w: %s", storage.ErrVolumeHeld, step.Reason)
	case StepWaitDetached, StepWaitAttached, StepDone:
		return step, nil
	}
	if err := reattacher.guard(ctx, epoch); err != nil {
		return step, err
	}
	switch step.Kind {
	case StepDetach:
		err := reattacher.Volumes.DetachFenced(ctx, request, step.Attachment, proof)
		if err == nil {
			recordFencedDetach(ctx, epoch, request, proof, step.Attachment)
		}
		return step, err
	case StepAttach:
		attached, err := reattacher.Volumes.AttachReplacement(ctx, request, proof)
		step.Attachment = attached
		if err == nil {
			recordReattach(ctx, epoch, request, proof, attached)
		}
		return step, err
	case StepGrantMount:
		err := reattacher.Permits.GrantMountExisting(ctx, request, step.Attachment)
		if err == nil {
			recordMountGranted(ctx, epoch, request, step.Attachment)
		}
		return step, err
	default:
		return step, fmt.Errorf("unknown reattach step %q", step.Kind)
	}
}

func (reattacher Reattacher) guard(ctx context.Context, epoch uint64) error {
	if snapshot := reattacher.Fencer.Current(); !snapshot.CanMutate() || snapshot.Epoch != epoch {
		return authority.ErrFenced
	}
	return reattacher.Fencer.Guard(ctx, epoch)
}

// recordReattach journals the replacement attach once per attach key: the
// attach is idempotent on that key, so a retried step does not duplicate it.
func recordReattach(ctx context.Context, epoch uint64, request Request, proof FenceProof, attached Attachment) {
	key := "reattach:" + request.AttachKey
	if decisionlog.Correlated(key) != "" {
		return
	}
	id := decisionlog.Record(ctx, decisionlog.Decision{
		Actor:   decisionlog.Actor{Slice: "storage"},
		Kind:    decisionlog.KindVolumeReattached,
		Subject: decisionlog.Subject{Kind: "volume", ID: request.VolumeID},
		Summary: "Reattached volume " + request.VolumeID + " to replacement instance " + request.ReplacementInstanceID,
		Reason:  "The previous writer instance was proven fenced (" + proof.State + ").",
		Rule:    "storage.reattach_on_host_loss",
		Signals: []decisionlog.Signal{{Name: "old_instance_state", Text: proof.State}},
		Status:  decisionlog.StatusInProgress,
		Epoch:   epoch,
		Attrs: map[string]string{"database": request.DatabaseID, "partition": request.PartitionID,
			"old_instance": request.OldInstanceID, "attachment": attached.ID},
	})
	decisionlog.Correlate(key, id)
}

// recordFencedDetach journals the detach of the lost instance's attachment,
// once per attachment, before the replacement attach.
func recordFencedDetach(ctx context.Context, epoch uint64, request Request, proof FenceProof, attachment Attachment) {
	key := "reattach-detach:" + request.AttachKey + ":" + attachment.ID
	if decisionlog.Correlated(key) != "" {
		return
	}
	id := decisionlog.Record(ctx, decisionlog.Decision{
		Actor:   decisionlog.Actor{Slice: "storage"},
		Kind:    decisionlog.KindVolumeReattached,
		Subject: decisionlog.Subject{Kind: "volume", ID: request.VolumeID},
		Summary: "Detached volume " + request.VolumeID + " from lost instance " + request.OldInstanceID,
		Reason:  "OCI reports the lost instance " + proof.State + ", so it can no longer write.",
		Rule:    "storage.reattach_on_host_loss",
		Signals: []decisionlog.Signal{{Name: "old_instance_state", Text: proof.State},
			{Name: "old_attachment_state", Text: attachment.State}},
		Status: decisionlog.StatusInProgress,
		Epoch:  epoch,
		Attrs: map[string]string{"database": request.DatabaseID, "partition": request.PartitionID,
			"old_instance": request.OldInstanceID, "attachment": attachment.ID},
	})
	decisionlog.Correlate(key, id)
}

// recordMountGranted closes the reattach chain: the replacement may mount
// the existing filesystem and is never allowed to format it.
func recordMountGranted(ctx context.Context, epoch uint64, request Request, attachment Attachment) {
	key := "reattach-mount:" + request.AttachKey
	if decisionlog.Correlated(key) != "" {
		return
	}
	id := decisionlog.Record(ctx, decisionlog.Decision{
		Actor:    decisionlog.Actor{Slice: "storage"},
		Kind:     decisionlog.KindVolumeReattached,
		Subject:  decisionlog.Subject{Kind: "volume", ID: request.VolumeID},
		Summary:  "Granted a mount-existing permit for volume " + request.VolumeID + " on its replacement instance",
		Reason:   "The volume is attached only to the replacement; its filesystem is mounted as is and never formatted.",
		Rule:     "storage.reattach_on_host_loss",
		Status:   decisionlog.StatusSucceeded,
		Epoch:    epoch,
		ParentID: decisionlog.Correlated("reattach:" + request.AttachKey),
		Attrs: map[string]string{"database": request.DatabaseID, "partition": request.PartitionID,
			"replacement_instance": request.ReplacementInstanceID, "attachment": attachment.ID},
	})
	decisionlog.Correlate(key, id)
}

