material_path_builder.text:
func runtimePaths(root string, launch ManagedMemberLaunch) (managedRuntimePaths, error) {
	if !filepath.IsAbs(root) || filepath.Clean(root) != root || root == "/" {
		return managedRuntimePaths{}, errors.New("managed runtime root must be a clean absolute directory")
	}
	scope := launch.Member.Scope
	if err := validateManagedMemberBinding(launch.Member); err != nil {
		return managedRuntimePaths{}, err
	}
	sum := sha256.Sum256([]byte(scope.ClusterID + "/" + scope.TenantID + "/" + scope.DatabaseID + "/" +
		strconv.FormatUint(scope.ShardID, 10) + "/" + scope.MemberID + "/" + scope.Incarnation + "/" +
		strconv.FormatUint(launch.Member.HostAttempt, 10)))
	memberDir := filepath.Join(root, hex.EncodeToString(sum[:16]))
	paths := managedRuntimePaths{
		memberDir:  memberDir,
		mount:      filepath.Join(memberDir, "volume"),
		material:   filepath.Join(memberDir, "material"),
		socket:     filepath.Join(memberDir, "control", "member.sock"),
		nativeRoot: filepath.Join(memberDir, "native-root.sock"),
	}
	if len(paths.socket) >= 108 || len(paths.nativeRoot) >= 108 {
		return managedRuntimePaths{}, errors.New("managed socket path exceeds Unix limit")
	}
	return paths, nil
}

registration_binding.text:
func ValidateManagedRegistrationPins(registration Registration, pins ManagedRegistrationPins) error {
	if registration.ManagedPlacement == nil || *registration.ManagedPlacement != pins.Placement ||
		registration.ManagedMember == nil || *registration.ManagedMember != pins.Member ||
		registration.ManagedOCI == nil || *registration.ManagedOCI != pins.OCI ||
		registration.FailureDomain != pins.FailureDomain || pins.AllocatableMemoryBytes > math.MaxInt64 ||
		registration.Capacity.MemoryBytes != int64(pins.AllocatableMemoryBytes) || pins.SystemReserveBytes > math.MaxInt64 ||
		registration.SystemReserveBytes != int64(pins.SystemReserveBytes) {
		return errors.New("managed registration differs from current placement pins")
	}
	return nil
}

func validateManagedMemberBinding(binding ManagedMemberBinding) error {
	scope := binding.Scope
	if !lowerHexIdentity(scope.ClusterID) || !lowerHexIdentity(scope.Incarnation) ||
		!canonicalMemberID(scope.TenantID) || !canonicalMemberID(scope.DatabaseID) ||
		!canonicalMemberID(scope.MemberID) || scope.ShardID == 0 || binding.HostAttempt == 0 {
		return errors.New("managed member identity is invalid")
	}
	return nil
}

report_age.text:
// ReportMaxAge is how old a host's latest report may be and still count as
// current. Hosts report once per reconcile, which takes up to about half a
// minute on a single-OCPU host; liveness is still bounded by the host session,
// and every managed proof is bound to the exact reported process.
const ReportMaxAge = 90 * time.Second

serving_identity.text:
func (s Scope) valid() bool {
	return lowerHexIdentity(s.ClusterID) && lowerHexIdentity(s.Incarnation) && s.ShardID != 0 &&
		canonicalID(s.TenantID) && canonicalID(s.DatabaseID) && canonicalID(s.MemberID)
}

func (a Authority) valid() bool {
	return a.Epoch != 0 && lowerHex(a.ConfigurationID, 64) &&
		lowerHex(a.CertificateSHA256, 64) && lowerHex(a.TLSLeafSHA256, 64)
}

func (p Process) valid() bool { return p.PID >= 1 && lowerHex(p.StartNonce, 32) }

func (s Survivor) valid() bool {
	return canonicalID(s.MemberID) && lowerHexIdentity(s.Incarnation)
}

func lowerHex(value string, length int) bool {
	if len(value) != length {
		return false
	}
	for i := range len(value) {
		if value[i] < '0' || value[i] > '9' {
			if value[i] < 'a' || value[i] > 'f' {
				return false
			}
		}
	}
	return true
}

func canonicalID(value string) bool { return entityid.Valid(value) }

crypto_envelope.text:
func KeyID(publicKey ed25519.PublicKey) (string, error) {
	if len(publicKey) != ed25519.PublicKeySize {
		return "", fmt.Errorf("%w: expected an Ed25519 public key", ErrInvalidEnvelope)
	}
	digest := sha256.Sum256(publicKey)
	return "sha256:" + hex.EncodeToString(digest[:]), nil
}

// SignEnvelope signs compacted raw JSON payload bytes and their complete scope.
// Payload object member order remains significant; insignificant JSON whitespace
// is removed before signing and stored in the returned envelope.
func SignEnvelope(
	payload []byte,
	scope EnvelopeScope,
	issuedAt time.Time,
	expiresAt time.Time,
	privateKey ed25519.PrivateKey,
) (Envelope, error) {
	if len(privateKey) != ed25519.PrivateKeySize {
		return Envelope{}, fmt.Errorf("%w: expected an Ed25519 private key", ErrInvalidEnvelope)
	}
	normalized, err := normalizeScope(scope)
	if err != nil {
		return Envelope{}, err
	}
	issuedAt = issuedAt.Round(0).UTC()
	expiresAt = expiresAt.Round(0).UTC()
	if !validProtocolTime(issuedAt) || !validProtocolTime(expiresAt) || !expiresAt.After(issuedAt) {
		return Envelope{}, fmt.Errorf("%w: issuedAt and expiresAt must form a valid UTC interval", ErrInvalidEnvelope)
	}
	compactPayload, err := compactPayload(payload)
	if err != nil {
		return Envelope{}, err
	}
	publicKey := privateKey.Public().(ed25519.PublicKey)
	keyID, err := KeyID(publicKey)
	if err != nil {
		return Envelope{}, err
	}
	envelope := Envelope{
		SchemaVersion: EnvelopeSchemaVersion,
		Region:        normalized.Region,
		Kind:          normalized.Kind,
		Actor:         normalized.Actor,
		Generation:    normalized.Generation,
		Epoch:         normalized.Epoch,
		OperationID:   normalized.OperationID,
		IssuedAt:      issuedAt,
		ExpiresAt:     expiresAt,
		KeyID:         keyID,
		Payload:       compactPayload,
	}
	material, err := signedMaterial(envelope)
	if err != nil {
		return Envelope{}, err
	}
	envelope.Signature = base64.RawURLEncoding.EncodeToString(ed25519.Sign(privateKey, material))
	return envelope, nil
}

// VerifyEnvelope verifies signature, exact semantic scope, expiry, and fencing
// metadata. Replay prevention for OperationID belongs to the durable consumer.
func VerifyEnvelope(
	envelope Envelope,
	expected EnvelopeScope,
	publicKey ed25519.PublicKey,
	now time.Time,
	policy VerifyPolicy,
) error {
	if len(publicKey) != ed25519.PublicKeySize || policy.MaxLifetime <= 0 || policy.ClockSkew < 0 || !validProtocolTime(now) {
		return ErrInvalidPolicy
	}
	if envelope.SchemaVersion != EnvelopeSchemaVersion {
		return fmt.Errorf("%w: unsupported schema version", ErrInvalidEnvelope)
	}
	actualScope, err := normalizeScope(EnvelopeScope{
		Region: envelope.Region, Kind: envelope.Kind, Actor: envelope.Actor,
		OperationID: envelope.OperationID, Generation: envelope.Generation, Epoch: envelope.Epoch,
	})
	if err != nil {
		return err
	}
	expectedScope, err := normalizeScope(expected)
	if err != nil {
		return err
	}
	if actualScope != expectedScope {
		return ErrScopeMismatch
	}
	if !validProtocolTime(envelope.IssuedAt) || !validProtocolTime(envelope.ExpiresAt) ||
		!envelope.ExpiresAt.After(envelope.IssuedAt) ||
		envelope.ExpiresAt.Sub(envelope.IssuedAt) > policy.MaxLifetime {
		return fmt.Errorf("%w: invalid timestamp interval", ErrInvalidEnvelope)
	}
	issuedAt := envelope.IssuedAt.Round(0).UTC()
	expiresAt := envelope.ExpiresAt.Round(0).UTC()
	if issuedAt.Sub(now) > policy.ClockSkew {
		return ErrNotYetValid
	}
	if !now.Before(expiresAt) {
		return ErrExpired
	}
	expectedKeyID, err := KeyID(publicKey)
	if err != nil {
		return err
	}
	if envelope.KeyID != expectedKeyID {
		return ErrKeyMismatch
	}
	compact, err := compactPayload(envelope.Payload)
	if err != nil {
		return err
	}
	envelope.Region = actualScope.Region
	envelope.Kind = actualScope.Kind
	envelope.Actor = actualScope.Actor
	envelope.OperationID = actualScope.OperationID
	envelope.IssuedAt = issuedAt
	envelope.ExpiresAt = expiresAt
	envelope.Payload = compact
	material, err := signedMaterial(envelope)
	if err != nil {
		return err
	}
	signature, err := base64.RawURLEncoding.DecodeString(envelope.Signature)
	if err != nil || len(signature) != ed25519.SignatureSize || !ed25519.Verify(publicKey, material, signature) {
		return ErrBadSignature
	}
	return nil
}

